window.lessonData = [{"category": "School Life", "topics": [{"title": "First Days and New People (12 questions)", "slug": "firstdaynewpeople", "level": "A2-B1", "questions": [{"original": "If you could start at a new school with one friend already by your side, who would you choose and why?", "paraphrased": "Who is the one person who would make a brand-new school feel safe from the first morning?", "vocab": [{"word": "brand-new", "definition": "completely new, never used before", "translation": ""}, {"word": "by your side", "definition": "next to you, supporting you", "translation": ""}], "possibleAnswers": ["My best friend from primary school, because we laugh at the same silly things.", "I would pick my cousin. We are used to each other, so I would not feel shy.", "No one, really. I like walking in alone and seeing who is friendly."]}, {"original": "What is the best thing someone said or did on your very first day at school?", "paraphrased": "Which small moment from your first day still makes you smile when you remember it?", "vocab": [{"word": "very first", "definition": "the first one, before any others", "translation": ""}, {"word": "still", "definition": "even now, after all this time", "translation": ""}], "possibleAnswers": ["A girl in my class shared her pen with me, and that tiny thing helped a lot.", "The teacher remembered my name on the second day, which felt really good.", "Nothing special happened, but I was proud that I found my classroom without help."]}, {"original": "Would you rather be the new student who joins halfway through the year, or the one who starts on the first day with everyone else?", "paraphrased": "Is it easier to arrive when the class is new, or when the class already knows each other?", "vocab": [{"word": "halfway", "definition": "in the middle of something", "translation": ""}, {"word": "already", "definition": "before now; done", "translation": ""}], "possibleAnswers": ["Starting on the first day, because everyone is nervous together.", "Honestly, joining halfway is fine for me. I like one or two close friends, not a big group.", "The first day. On day one nobody has formed groups yet, so it is easier to fit in."]}, {"original": "If you could design the perfect first-day activity for new students, what would it be?", "paraphrased": "What game or task would make a room full of strangers start talking to each other?", "vocab": [{"word": "design", "definition": "to plan and create something carefully", "translation": ""}, {"word": "stranger", "definition": "a person you have never met before", "translation": ""}], "possibleAnswers": ["A treasure hunt around the school, because you have to ask people for clues.", "A simple quiz in pairs, like 'find three things you have in common'.", "A sports afternoon. When you play together, nobody stays quiet for long."]}, {"original": "What is the most useful thing a teacher can do to help new students settle in?", "paraphrased": "Which teacher habit makes the first week feel much less scary for someone new?", "vocab": [{"word": "useful", "definition": "helpful; it does a good job for you", "translation": ""}, {"word": "settle in", "definition": "to become comfortable in a new place", "translation": ""}], "possibleAnswers": ["Show them the building and introduce them to one friendly classmate.", "Do not call on them to answer in front of everyone on the first day.", "Give them a small job, like handing out books. It gives them a reason to talk."]}, {"original": "Who would you go to first if you felt lost in the first week of a new school?", "paraphrased": "Which person would you look for before anyone else?", "vocab": [{"word": "lost", "definition": "not knowing where you are or what to do", "translation": ""}, {"word": "look for", "definition": "to try to find someone or something", "translation": ""}], "possibleAnswers": ["The school office. The people there always know where everything is.", "A student in the same year. Students understand better than teachers do.", "My older sister. She went to my school, so she could explain all the strange rules."]}, {"original": "What is your favourite way to start a conversation with someone you have never met?", "paraphrased": "Which opening line actually works for you when you meet a new classmate?", "vocab": [{"word": "conversation", "definition": "a talk between two or more people", "translation": ""}, {"word": "opening line", "definition": "the first thing you say in a conversation", "translation": ""}], "possibleAnswers": ["I ask about the lesson, like 'did you understand the homework?' It is easy to answer.", "I just say hello and ask where they are from.", "I make a small joke about the weather or the food. It breaks the ice."]}, {"original": "If you could change one thing about how your school welcomes new students, what would it be?", "paraphrased": "Which part of the first week would you fix so that new students feel more welcome?", "vocab": [{"word": "welcome", "definition": "to greet someone kindly and make them feel at home", "translation": ""}, {"word": "fix", "definition": "to repair or improve something that is not working", "translation": ""}], "possibleAnswers": ["A buddy system, so every new student gets one person who looks after them.", "Less talking at the front. A quick tour of the building helps more.", "I would invite new students to eat lunch with a group from the first day."]}, {"original": "Do you agree that the first week at a new school says everything about how the whole year will go?", "paraphrased": "Can you tell, from those first few days, whether the year will be good or bad?", "vocab": [{"word": "agree", "definition": "to have the same opinion as someone else", "translation": ""}, {"word": "whole", "definition": "complete; including every part", "translation": ""}], "possibleAnswers": ["I do. People show their real character in the first few days.", "Not at all. Someone who seems quiet at first can become your best friend later.", "A bit. The first week gives you a feeling, but things always change."]}, {"original": "What advice would you give to a younger student who is nervous about their first day at your school?", "paraphrased": "What would you tell a nervous 11-year-old the night before they join your school?", "vocab": [{"word": "advice", "definition": "helpful words that tell someone what to do", "translation": ""}, {"word": "nervous", "definition": "worried or a little afraid about something that will happen", "translation": ""}], "possibleAnswers": ["Sleep well and take a pen you like. Small things make you feel ready.", "Remember that everyone else is nervous too, even if they do not show it.", "Find one person to smile at. One friendly face is enough for the first day."]}, {"original": "When you think back to your own first day at secondary school, what picture do you remember most clearly?", "paraphrased": "Which single image from that morning stays in your mind?", "vocab": [{"word": "think back", "definition": "to remember something from the past", "translation": ""}, {"word": "clearly", "definition": "in a way that is easy to see or remember", "translation": ""}], "possibleAnswers": ["I remember my mum waving at the gate, and feeling both excited and scared.", "The huge corridor, and how loud everyone sounded.", "Sitting at a desk next to a boy who is now my best friend."]}, {"original": "If you had to describe your first day at school in three words, which three would you pick?", "paraphrased": "Which three words would sum up that day for someone who was not there?", "vocab": [{"word": "describe", "definition": "to say what something or someone is like", "translation": ""}, {"word": "sum up", "definition": "to explain the main points in a short way", "translation": ""}], "possibleAnswers": ["Big, loud, and interesting. I could not stop looking around.", "Quiet, strange, and a bit sad. I missed my old school.", "Fast, friendly, and surprisingly normal."]}]}, {"title": "Teachers and Homework (12 questions)", "slug": "teachersandhomework", "level": "A2-B1", "questions": [{"original": "What is the most important quality a teacher can have when working with teenagers?", "paraphrased": "Which teacher trait matters most to you: humour, fairness, patience, or something else?", "vocab": [{"word": "quality", "definition": "a good or bad part of someone's character", "translation": ""}, {"word": "fairness", "definition": "treating everyone in the same, honest way", "translation": ""}], "possibleAnswers": ["Patience. A teacher who stays calm when we do not understand.", "A sense of humour. Lessons go faster when the teacher makes us laugh.", "Fairness. I like a teacher who listens to every student, not just the loud ones."]}, {"original": "If you could give your teachers one piece of feedback about homework, what would it be?", "paraphrased": "What would you change about the way your teachers set homework?", "vocab": [{"word": "feedback", "definition": "useful comments about someone's work or behaviour", "translation": ""}, {"word": "set", "definition": "to give or assign a task to someone", "translation": ""}], "possibleAnswers": ["Less of it, but harder tasks. One good question beats ten easy ones.", "Let us choose the topic sometimes. Then we care more about the answer.", "Stop giving homework before holidays. We need a real break."]}, {"original": "Which teacher has helped you the most this year, and what exactly did they do?", "paraphrased": "What did that teacher do that made a real difference for you?", "vocab": [{"word": "exactly", "definition": "in a precise way; with no doubt", "translation": ""}, {"word": "difference", "definition": "a change that makes something better or worse", "translation": ""}], "possibleAnswers": ["My maths teacher stayed after class with me until the method finally made sense.", "My English teacher wrote one kind sentence on my essay, and I kept it.", "My science teacher never made me feel silly for asking the same question twice."]}, {"original": "Would you rather have a teacher who is very strict but explains clearly, or a teacher who is friendly but sometimes confusing?", "paraphrased": "Which matters more to you in a lesson: clear explanations or a warm personality?", "vocab": [{"word": "strict", "definition": "expecting rules to be followed; not relaxed", "translation": ""}, {"word": "confusing", "definition": "difficult to understand; not clear", "translation": ""}], "possibleAnswers": ["Strict but clear. I can work with rules if I know what to do.", "Friendly but confusing, because I like the teacher, so I try harder.", "Neither. The best teachers are clear and kind at the same time."]}, {"original": "What is the worst excuse for not doing your homework that a teacher has ever heard from you or someone else?", "paraphrased": "Which homework excuse made you laugh, even though you knew it would not work?", "vocab": [{"word": "excuse", "definition": "a reason you give for not doing something, often not true", "translation": ""}, {"word": "even though", "definition": "despite the fact that; although", "translation": ""}], "possibleAnswers": ["'My dog ate my homework' is so old that teachers laugh at it now.", "A friend said the internet broke at his house. The teacher said, 'Then write it by hand.'", "I once said I forgot my bag at school. The teacher just looked at me and smiled."]}, {"original": "If homework did not exist, what would you spend that extra hour doing instead?", "paraphrased": "What would an extra free hour after school look like for you?", "vocab": [{"word": "instead", "definition": "in place of something else", "translation": ""}, {"word": "extra", "definition": "more than usual; additional", "translation": ""}], "possibleAnswers": ["Football in the park with my friends until it gets dark.", "Reading a book I actually chose, not one from school.", "Sleeping. I am always tired, and that hour would be a gift."]}, {"original": "What is your favourite subject, and what does the teacher do that makes it your favourite?", "paraphrased": "Which lesson do you look forward to, and which teacher habit makes it special?", "vocab": [{"word": "look forward to", "definition": "to feel excited about something that is coming", "translation": ""}, {"word": "habit", "definition": "something you do often, almost without thinking", "translation": ""}], "possibleAnswers": ["History, because our teacher tells the stories like they happened yesterday.", "Art. The teacher lets us draw while she talks, and I concentrate better.", "PE, because our teacher joins in and we all play together."]}, {"original": "Do you think students should be allowed to mark their own homework in class?", "paraphrased": "Would it be a good idea for us to check our own answers together?", "vocab": [{"word": "allowed", "definition": "given permission to do something", "translation": ""}, {"word": "mark", "definition": "to check work and give it a grade or score", "translation": ""}], "possibleAnswers": ["Yes. You learn more from your own mistakes when you see them yourself.", "No. Some students would just copy the answers and learn nothing.", "Sometimes, for easy exercises, but teachers should check the important ones."]}, {"original": "What advice would you give a teacher who wants to make homework less boring?", "paraphrased": "What would you tell a teacher about how to make homework something students do not hate?", "vocab": [{"word": "boring", "definition": "not interesting; making you feel tired of it", "translation": ""}, {"word": "hate", "definition": "to dislike something very much", "translation": ""}], "possibleAnswers": ["Use real life. Ask us to write a message to a friend, not fill in a worksheet.", "Let us work in pairs sometimes. Homework feels easier with a friend.", "Keep it short. Ten minutes of good work is better than an hour of copying."]}, {"original": "When you sit down to do homework, what is the first thing you do to get started?", "paraphrased": "What is your routine for beginning homework, and does it work?", "vocab": [{"word": "routine", "definition": "the usual way you do something, in the same order", "translation": ""}, {"word": "get started", "definition": "to begin doing something", "translation": ""}], "possibleAnswers": ["I put my phone in another room. That is the only thing that works.", "I have a snack first, then I open my books.", "I read through all the tasks and choose the easiest one first."]}, {"original": "If you could swap one school subject with another for a whole week, which two would you swap and why?", "paraphrased": "Which two lessons would you exchange, and what would you hope to learn instead?", "vocab": [{"word": "swap", "definition": "to exchange one thing for another", "translation": ""}, {"word": "whole", "definition": "complete; from beginning to end", "translation": ""}], "possibleAnswers": ["History and geography. I would rather have two long PE lessons.", "Maths and physics, because they feel similar and I could focus on one.", "I would swap a morning subject for an art lesson, so the day starts nicely."]}, {"original": "Who in your class does their homework first, and who leaves it until the last minute?", "paraphrased": "Which of your classmates has the best homework habit, and what can you learn from them?", "vocab": [{"word": "last minute", "definition": "the latest possible time before something is due", "translation": ""}, {"word": "classmate", "definition": "another student in your class", "translation": ""}], "possibleAnswers": ["My friend Ana does hers on the bus home. I could never concentrate like that.", "The quiet boy at the back. He finishes early and then helps other people.", "Honestly, I leave everything until Sunday night, and I would like to change that."]}]}, {"title": "Exams and Stress (12 questions)", "slug": "examsandstress", "level": "A2-B1", "questions": [{"original": "What does stress feel like in your body when you are waiting for an exam result?", "paraphrased": "Which physical sign tells you that you are stressed, and how do you handle it?", "vocab": [{"word": "stress", "definition": "a feeling of worry or pressure that makes it hard to relax", "translation": ""}, {"word": "physical", "definition": "connected with your body, not your mind", "translation": ""}], "possibleAnswers": ["My hands get cold and I cannot sit still. I usually go for a walk.", "I get a headache and want to sleep all day.", "My stomach feels strange. I eat something light and talk to my mum."]}, {"original": "If you could take one exam again, knowing everything you know now, which one would it be?", "paraphrased": "Which past exam would you redo with all your experience and calm?", "vocab": [{"word": "redo", "definition": "to do something again", "translation": ""}, {"word": "calm", "definition": "relaxed and not worried or excited", "translation": ""}], "possibleAnswers": ["My science test in year eight. I knew the answers, I just panicked.", "The maths exam where I forgot half the formulas. I would sleep well first.", "None. I would rather focus on the next one than look back."]}, {"original": "Do you study better alone in your room, or with friends in a group?", "paraphrased": "Which study setup actually helps you remember things?", "vocab": [{"word": "setup", "definition": "the way something is arranged or organised", "translation": ""}, {"word": "remember", "definition": "to keep something in your mind so you can use it later", "translation": ""}], "possibleAnswers": ["Alone. One friend in the room and I stop working completely.", "In a group, as long as everyone stays focused. We test each other.", "Both. Alone for hard topics, with friends for easy revision."]}, {"original": "What is the best thing a friend can say to you the night before a big exam?", "paraphrased": "Which sentence from a friend would actually calm you down before a test?", "vocab": [{"word": "the night before", "definition": "on the evening before something happens", "translation": ""}, {"word": "calm down", "definition": "to become less worried, nervous, or excited", "translation": ""}], "possibleAnswers": ["'You have done the work. Now just sleep.' That helps more than advice.", "'We will both pass. Let us stop studying and watch something funny.'", "Nothing. A hug is better than any words."]}, {"original": "If you could design a stress-free exam day, what would it look like from morning to night?", "paraphrased": "How would a perfect, calm exam day be organised, from breakfast to bedtime?", "vocab": [{"word": "stress-free", "definition": "without worry or pressure", "translation": ""}, {"word": "organised", "definition": "planned carefully and arranged well", "translation": ""}], "possibleAnswers": ["A short morning revision, then a walk, then the exam, then time with friends.", "No talking about the exam at school. Teachers just smile and say good luck.", "An exam in the afternoon, so I can sleep properly in the morning."]}, {"original": "Which subject makes you feel the most nervous before a test, and why?", "paraphrased": "Which exam subject is the one you dread the most, and what makes it hard?", "vocab": [{"word": "nervous", "definition": "worried or a little afraid about something that will happen", "translation": ""}, {"word": "dread", "definition": "to feel very worried about something you will have to do", "translation": ""}], "possibleAnswers": ["Maths. One small mistake and the whole answer is wrong.", "Languages. I worry about speaking in front of the teacher.", "History. There is so much to remember, and I never know what they will ask."]}, {"original": "What is the worst advice about exams that someone has given you?", "paraphrased": "Which thing people say about exams actually makes you feel worse?", "vocab": [{"word": "advice", "definition": "helpful words that tell someone what to do", "translation": ""}, {"word": "worse", "definition": "more bad; the opposite of better", "translation": ""}], "possibleAnswers": ["'Do not be nervous.' As if I can just switch it off.", "'This exam decides your whole life.' Thanks, that helps a lot.", "'Just relax and it will be fine.' Easy to say when it is not your exam."]}, {"original": "If your school cancelled all exams for one year, what would you miss and what would you celebrate?", "paraphrased": "What would you lose and what would you gain without exams for a year?", "vocab": [{"word": "cancelled", "definition": "stopped or called off before it happened", "translation": ""}, {"word": "celebrate", "definition": "to show happiness about something special", "translation": ""}], "possibleAnswers": ["I would celebrate sleeping, but I might miss the feeling of finishing something hard.", "Nothing to miss. A whole year of normal lessons sounds perfect.", "I would miss the challenge. I like proving to myself that I can do it."]}, {"original": "How do you plan your revision so that you are not trying to learn everything on the last day?", "paraphrased": "What revision routine stops the panic of leaving everything too late?", "vocab": [{"word": "revision", "definition": "studying again before a test", "translation": ""}, {"word": "panic", "definition": "a sudden strong feeling of fear that makes it hard to think", "translation": ""}], "possibleAnswers": ["I write a timetable and do a little of each subject every week.", "I make small cards with the key facts and look at them on the bus.", "I ask my friends what they think will be in the test, and we cover that together."]}, {"original": "Who do you talk to when exams feel too heavy, and what do they say?", "paraphrased": "Which person helps you most when the pressure is too much?", "vocab": [{"word": "heavy", "definition": "difficult to carry or deal with; serious", "translation": ""}, {"word": "pressure", "definition": "a feeling of being forced to do something well", "translation": ""}], "possibleAnswers": ["My older brother. He says his exams felt huge too, and he survived.", "My best friend. We complain together and then feel normal again.", "Nobody, usually. I write it down in a notebook instead."]}, {"original": "Would you rather have one very long exam at the end of the year, or several short tests spread across the year?", "paraphrased": "Which exam system would you choose, and why does it suit you better?", "vocab": [{"word": "spread", "definition": "arranged across a period of time, not all together", "translation": ""}, {"word": "suit", "definition": "to be right or good for someone", "translation": ""}], "possibleAnswers": ["Short tests. I forget everything if I have to remember it for months.", "One long exam. I only want to worry once a year.", "Short tests, but with a chance to improve the worst one later."]}, {"original": "If you could give your future self one message before your next exam, what would it say?", "paraphrased": "What short sentence would you send to yourself on exam morning?", "vocab": [{"word": "future", "definition": "the time that is coming; what has not happened yet", "translation": ""}, {"word": "message", "definition": "words you send to someone, like a note or text", "translation": ""}], "possibleAnswers": ["'Breathe. You have prepared. Do the easy questions first.'", "'This is one day, not your whole life. Just do your best.'", "'Remember the time you thought you failed and then passed.'"]}]}, {"title": "School Rules and Uniforms (12 questions)", "slug": "schoolrules", "level": "A2-B1", "questions": [{"original": "What is one school rule that you think is a good idea, and why does it work?", "paraphrased": "Which rule at your school actually helps students, and what makes it sensible?", "vocab": [{"word": "sensible", "definition": "reasonable and practical; easy to agree with", "translation": ""}, {"word": "actually", "definition": "in fact; really", "translation": ""}], "possibleAnswers": ["No phones in class. It helps everyone concentrate.", "We have to wear our uniform correctly. It makes the mornings much faster.", "A rule about being on time. It is fair to the teacher and the class."]}, {"original": "If you could change one rule at your school, which rule would you change and what would you replace it with?", "paraphrased": "Which rule would you rewrite, and what would the new version be?", "vocab": [{"word": "rewrite", "definition": "to write something again in a different way", "translation": ""}, {"word": "replace", "definition": "to put something new where something old was", "translation": ""}], "possibleAnswers": ["The rule about skirts and trousers. I would let everyone choose either.", "The lunch rule. I would let us eat outside when the weather is nice.", "The phone rule at break. I would allow phones for ten minutes between lessons."]}, {"original": "Do you think school uniforms make life easier or harder for teenagers?", "paraphrased": "Are uniforms a help or a problem for students your age?", "vocab": [{"word": "uniform", "definition": "special clothes that all students at a school wear", "translation": ""}, {"word": "teenager", "definition": "a person between 13 and 19 years old", "translation": ""}], "possibleAnswers": ["Easier. I do not have to think about what to wear every morning.", "Harder. They are uncomfortable and we still find ways to be different.", "Both. Easy mornings, but we lose a bit of who we are."]}, {"original": "What is the strangest rule you have ever heard of at a school anywhere in the world?", "paraphrased": "Which unusual school rule would surprise students in your country?", "vocab": [{"word": "strangest", "definition": "the most unusual or surprising", "translation": ""}, {"word": "unusual", "definition": "not normal; different from what you expect", "translation": ""}], "possibleAnswers": ["A school that bans talking in the corridor. I would not last one day.", "A school where students have to bow to the teacher at the door.", "A rule that you cannot wear your hair in a certain colour. That seems unfair."]}, {"original": "Would you rather have a school with very few rules but strict consequences, or many rules that are never enforced?", "paraphrased": "Which school system would you prefer: few serious rules or lots of forgotten ones?", "vocab": [{"word": "consequence", "definition": "what happens to you after you break a rule", "translation": ""}, {"word": "enforce", "definition": "to make sure a rule is obeyed", "translation": ""}], "possibleAnswers": ["Few rules, strict consequences. At least you know where you stand.", "Many rules, not enforced. Life is more relaxed, even if it is a bit messy.", "Neither. Rules should be clear and used fairly."]}, {"original": "What is the best reason a school can give for a rule that students do not like?", "paraphrased": "Which explanation makes an unpopular rule easier to accept?", "vocab": [{"word": "reason", "definition": "the explanation for why something happens", "translation": ""}, {"word": "unpopular", "definition": "not liked by most people", "translation": ""}], "possibleAnswers": ["'It keeps you safe.' Safety is a reason I can accept.", "'It is fair for everyone.' I like fairness, even when I do not like the rule.", "'It helps you learn.' If it truly helps, I will follow it."]}, {"original": "If you were headteacher for one day, what would you do first?", "paraphrased": "What would be the very first change you would make as headteacher?", "vocab": [{"word": "headteacher", "definition": "the teacher in charge of a whole school", "translation": ""}, {"word": "first", "definition": "before anything else", "translation": ""}], "possibleAnswers": ["I would give everyone a free ice cream at lunch. Start with something kind.", "I would listen to the students' ideas before changing anything.", "I would cancel one homework task for the whole school."]}, {"original": "What advice would you give to a new student who is worried about breaking rules they do not know?", "paraphrased": "What would you tell a new student who is afraid of making a mistake with the rules?", "vocab": [{"word": "worried", "definition": "feeling anxious or concerned about something", "translation": ""}, {"word": "mistake", "definition": "something you do wrong", "translation": ""}], "possibleAnswers": ["Ask a friend or a teacher. Everyone understands that you are new.", "Watch what other students do for the first week.", "Do not worry. Teachers usually warn you before they give a punishment."]}, {"original": "Which rule do students at your school break most often, and why do they break it?", "paraphrased": "Which rule is the most ignored, and what makes students ignore it?", "vocab": [{"word": "ignore", "definition": "to pay no attention to a rule or person", "translation": ""}, {"word": "most often", "definition": "more frequently than anything else", "translation": ""}], "possibleAnswers": ["The phone rule. Everyone checks their phone when the teacher turns around.", "The rule about being quiet in the corridor. It is almost impossible.", "The uniform rule on shoes. Comfort wins every time."]}, {"original": "If your school asked students to help write three new rules, what three would you suggest?", "paraphrased": "Which three student-written rules would you propose, and why are they fair?", "vocab": [{"word": "suggest", "definition": "to offer an idea for others to consider", "translation": ""}, {"word": "propose", "definition": "to officially suggest a plan or idea", "translation": ""}], "possibleAnswers": ["Let us choose our own project topics. Let us eat outside in summer. Let us have a quiet room.", "No homework on birthdays. A student council that meets every month. Longer breaks.", "Fair phone rules, kind-language rules, and a rule that students can appeal a punishment."]}, {"original": "When you look at your uniform, what do you like about it and what would you change?", "paraphrased": "Which part of your uniform works well, and which part would you redesign?", "vocab": [{"word": "look at", "definition": "to turn your eyes towards something", "translation": ""}, {"word": "redesign", "definition": "to design something again to make it better", "translation": ""}], "possibleAnswers": ["I like the jumper because it is warm. I would change the shoes to something comfortable.", "I like the colours. I would like a lighter jacket for summer.", "Nothing much. It is fine, but I would add a small personal badge."]}, {"original": "Do you agree that students behave better when they are allowed to help make the rules?", "paraphrased": "Does having a say in the rules make students more likely to follow them?", "vocab": [{"word": "behave", "definition": "to act in a particular way", "translation": ""}, {"word": "likely", "definition": "probably going to happen", "translation": ""}], "possibleAnswers": ["Yes. If I helped write a rule, I would feel responsible for it.", "Not really. Students will still complain, even if they agreed.", "Sometimes. It works if the teachers truly listen, not just pretend to."]}]}, {"title": "Friends and Groups (12 questions)", "slug": "friendsandgroups", "level": "A2-B1", "questions": [{"original": "What is one thing a friend has done for you that you will never forget?", "paraphrased": "Which act of kindness from a friend still stays with you?", "vocab": [{"word": "act", "definition": "something you do; a deed", "translation": ""}, {"word": "kindness", "definition": "being friendly, generous, and caring towards others", "translation": ""}], "possibleAnswers": ["She sat with me at lunch when I was new and had nobody.", "He told me the truth about my bad grade, kindly, instead of lying.", "My friend walked home with me when I was upset and did not ask questions."]}, {"original": "If you could give your best friend one superpower for a week, what would it be and what would you do together?", "paraphrased": "Which superpower would you share with your closest friend, and how would you use it?", "vocab": [{"word": "superpower", "definition": "an impossible ability, like flying or reading minds", "translation": ""}, {"word": "closest", "definition": "the one you feel nearest to", "translation": ""}], "possibleAnswers": ["Time travel, so we could visit any century for a week of adventures.", "Invisibility, so we could explore the city without anyone seeing us.", "The power to talk to animals, then ask our cats what they really think."]}, {"original": "Would you rather have three close friends or ten friendly classmates?", "paraphrased": "Do you prefer a small, deep group or a big, easy one?", "vocab": [{"word": "close", "definition": "having a strong, personal relationship", "translation": ""}, {"word": "friendly", "definition": "kind and pleasant towards others", "translation": ""}], "possibleAnswers": ["Three close friends. I would rather be understood by a few people.", "Ten friendly classmates. School is more fun when everyone talks to you.", "Both, if possible. Close friends for hard days, friendly people for good days."]}, {"original": "What is the best way to make a new friend when you already have a group?", "paraphrased": "How can you welcome someone new without leaving your old friends behind?", "vocab": [{"word": "welcome", "definition": "to greet someone kindly and make them feel at home", "translation": ""}, {"word": "leave behind", "definition": "to abandon or forget someone", "translation": ""}], "possibleAnswers": ["Invite them to sit with us and ask them about their old school.", "Introduce them to one friend at a time, so it is not overwhelming.", "Include them in a game at break. Playing together is the fastest way."]}, {"original": "Do you think it is possible to stay friends with someone who moves to a different school?", "paraphrased": "Can a friendship survive when you no longer see each other every day?", "vocab": [{"word": "possible", "definition": "able to happen or be done", "translation": ""}, {"word": "survive", "definition": "to continue to exist, even when things are difficult", "translation": ""}], "possibleAnswers": ["Yes, if you message each other and meet up sometimes.", "It is hard. After a few months, you both have new friends.", "Sometimes. It depends on how close you were before."]}, {"original": "What is the worst thing a group of friends can do to someone who is different?", "paraphrased": "Which behaviour from a group is the most hurtful, and why?", "vocab": [{"word": "hurtful", "definition": "causing emotional pain", "translation": ""}, {"word": "different", "definition": "not the same as the others", "translation": ""}], "possibleAnswers": ["Leave them out on purpose. Silence is worse than an argument.", "Laugh at the way they speak or dress. That stays with a person.", "Pretend to be their friend and then talk about them behind their back."]}, {"original": "If your friends all wanted to do something you did not feel comfortable with, what would you do?", "paraphrased": "How would you say no without losing the friendship?", "vocab": [{"word": "comfortable", "definition": "feeling relaxed and safe; not worried", "translation": ""}, {"word": "lose", "definition": "to no longer have something", "translation": ""}], "possibleAnswers": ["I would say 'no, thanks' and suggest something else we could do.", "I would tell one friend the truth in private, and ask for support.", "I would go along once to see, but I would not do anything unsafe."]}, {"original": "What does a good friend do when you are having a bad day?", "paraphrased": "Which small action from a friend helps you most on a difficult day?", "vocab": [{"word": "action", "definition": "something that someone does", "translation": ""}, {"word": "difficult", "definition": "hard to do or deal with", "translation": ""}], "possibleAnswers": ["They listen and do not try to fix everything immediately.", "They make me laugh, even a little.", "They check on me the next day, so I know they remember."]}, {"original": "Who in your group of friends is the peacemaker, and how do they calm things down?", "paraphrased": "Which friend stops arguments, and what do they say or do?", "vocab": [{"word": "peacemaker", "definition": "someone who helps people stop fighting and agree again", "translation": ""}, {"word": "calm down", "definition": "to become less angry, upset, or excited", "translation": ""}], "possibleAnswers": ["My friend Sam changes the subject to something silly.", "My friend Ana says, 'We are all tired, let us talk tomorrow.'", "My friend just listens to both sides and finds the middle."]}, {"original": "If you could plan one perfect day out with your friends, where would you go and what would you do?", "paraphrased": "What would an ideal friendship day look like, from morning to evening?", "vocab": [{"word": "perfect", "definition": "with no faults; exactly what you want", "translation": ""}, {"word": "ideal", "definition": "the best possible; perfect in your imagination", "translation": ""}], "possibleAnswers": ["A beach day with music, food, and a long walk talking about everything.", "A city day: a museum, then a park, then a small café.", "A sleepover with films, games, and no alarm clock."]}, {"original": "What advice would you give to someone who feels like they do not fit into any group at school?", "paraphrased": "What would you say to a student who feels like an outsider?", "vocab": [{"word": "fit in", "definition": "to belong to a group and feel similar to the others", "translation": ""}, {"word": "outsider", "definition": "someone who is not accepted by a group", "translation": ""}], "possibleAnswers": ["Give it time. Groups change a lot between the ages of 12 and 16.", "Find one person, not a group. One friend is a real start.", "Join a club about something you love. Shared interests beat popularity."]}, {"original": "When you think of your friends three years from now, what do you hope stays the same?", "paraphrased": "Which part of your friendship do you want to still have in the future?", "vocab": [{"word": "hope", "definition": "to want something to happen", "translation": ""}, {"word": "stays", "definition": "continues to be the same", "translation": ""}], "possibleAnswers": ["The jokes only we understand. I want us to still laugh at them.", "The honesty. I hope we can still tell each other the truth.", "The feeling that we choose each other, not just because we are in the same class."]}]}]}, {"category": "Online Life", "topics": [{"title": "Social Media (12 questions)", "slug": "socialmedia", "level": "A2-B1", "questions": [{"original": "If you could delete one thing from the internet forever, what would it be and why?", "paraphrased": "Which kind of online content causes the most harm, and how would the internet change without it?", "vocab": [{"word": "delete", "definition": "To remove something completely so it no longer exists.", "translation": ""}, {"word": "harm", "definition": "Hurt or damage to a person or thing.", "translation": ""}], "possibleAnswers": ["I would delete anonymous hate comments, because they hurt people who are just trying to share their lives.", "I would delete fake news, because it can make people believe things that are not true.", "I would delete online bullying, because nobody should feel afraid of their own phone."]}, {"original": "Would you rather have a million followers or one best friend you can talk to about anything?", "paraphrased": "Is a huge audience worth more than a single person who truly understands you?", "vocab": [{"word": "follower", "definition": "A person who chooses to see your posts and updates.", "translation": ""}, {"word": "audience", "definition": "The group of people who watch, read or listen to your content.", "translation": ""}], "possibleAnswers": ["I would choose one best friend, because real support matters more than numbers.", "I would choose a million followers, because it could help me share important ideas.", "Neither is perfect, but I would take the friend who answers at midnight."]}, {"original": "What is your favourite thing to post about, and what does it say about you?", "paraphrased": "Which subject do you keep coming back to online, and why does it matter to you?", "vocab": [{"word": "post", "definition": "To share something, like a photo or message, on the internet.", "translation": ""}, {"word": "subject", "definition": "The thing you write, talk or think about.", "translation": ""}], "possibleAnswers": ["I post about my football team, because it shows how much I care about my friends and the game.", "I post my drawings, because they are the easiest way for me to say who I am.", "I post about books, because a good story is the best thing I can give someone."]}, {"original": "What is the worst thing about social media, and what is the best?", "paraphrased": "Which online habit makes you feel worse, and which one makes your feed better?", "vocab": [{"word": "habit", "definition": "Something you do often, sometimes without thinking about it.", "translation": ""}, {"word": "feed", "definition": "The stream of posts and pictures you see when you open an app.", "translation": ""}], "possibleAnswers": ["The worst part is comparing yourself with others, and the best part is finding people who share your interests.", "The worst part is wasting hours scrolling, and the best part is learning new skills from short videos.", "The worst part is arguments in the comments, and the best part is seeing faraway friends stay close."]}, {"original": "A younger student asks you how to stay safe online. What three tips would you give them?", "paraphrased": "What would you tell someone who is just starting to use social media and wants to stay safe?", "vocab": [{"word": "safe", "definition": "Not in danger and not likely to be harmed.", "translation": ""}, {"word": "tip", "definition": "A small piece of useful advice.", "translation": ""}], "possibleAnswers": ["I would say: use a strong password, never share your address, and only accept friend requests from people you know.", "I would tell them to think before they post, because a picture can stay online forever.", "I would tell them to talk to a trusted adult if a message makes them feel uncomfortable."]}, {"original": "If you had to live one week without any social media, what would you do with the extra time?", "paraphrased": "What activity would fill the hours you normally spend scrolling?", "vocab": [{"word": "scroll", "definition": "To move slowly through posts and pictures on a screen.", "translation": ""}, {"word": "activity", "definition": "Something you do that takes time and energy.", "translation": ""}], "possibleAnswers": ["I would read more books, because I always say I do not have time.", "I would play outside with my friends, because fresh air beats a screen.", "I would learn to cook, because it is useful and I would enjoy the results."]}, {"original": "Do you agree that people only show the good parts of their lives online?", "paraphrased": "Is social media a true picture of someone's life, or a highlight reel?", "vocab": [{"word": "agree", "definition": "To have the same opinion as someone else.", "translation": ""}, {"word": "highlight", "definition": "The most exciting or best part of something.", "translation": ""}], "possibleAnswers": ["Yes, because people usually post their happy moments and hide the boring or sad ones.", "No, because many people now share their problems too, and that can be honest and helpful.", "Mostly yes, but I think it is slowly changing as people talk more about mental health."]}, {"original": "Who do you follow online that makes you think differently, and what do they teach you?", "paraphrased": "Which creator challenges your ideas, and what have you learned from them?", "vocab": [{"word": "follow", "definition": "To subscribe to someone's updates so you see their new posts.", "translation": ""}, {"word": "creator", "definition": "A person who makes content for the internet.", "translation": ""}], "possibleAnswers": ["I follow a science teacher who makes me question what I think I know about the world.", "I follow a chef from another country, and she teaches me that food is a way to understand culture.", "I follow a climate activist who pushes me to think about my own habits."]}, {"original": "If you could design your own social media app, what one feature would you include?", "paraphrased": "What tool or button do you wish every platform had?", "vocab": [{"word": "design", "definition": "To plan how something will look and work.", "translation": ""}, {"word": "feature", "definition": "A useful part or function of an app or machine.", "translation": ""}], "possibleAnswers": ["I would add a kindness button that rewards helpful comments instead of just likes.", "I would add a timer that gently tells you when you have been online for an hour.", "I would add a button that shows both sides of a story, so people read before they share."]}, {"original": "Would you rather give up posting photos or give up watching videos for a month?", "paraphrased": "Which would you miss more: uploading your own moments or watching other people's?", "vocab": [{"word": "give up", "definition": "To stop doing or having something.", "translation": ""}, {"word": "upload", "definition": "To send a photo or file from your device to the internet.", "translation": ""}], "possibleAnswers": ["I would give up watching videos, because I love sharing my own photos.", "I would give up posting photos, because watching videos helps me relax after school.", "I would give up videos, because I would rather keep my memories than consume other people's."]}, {"original": "Imagine you wake up and every photo of you online has disappeared. How would you feel?", "paraphrased": "If your digital past vanished overnight, would you feel free or exposed?", "vocab": [{"word": "disappear", "definition": "To stop being visible or to go out of sight.", "translation": ""}, {"word": "exposed", "definition": "Having your private life shown without protection.", "translation": ""}], "possibleAnswers": ["I would feel free, because nobody could judge me for things I did years ago.", "I would feel exposed at first, but then relieved that my mistakes were gone.", "I would feel sad, because those photos are my memories with friends and family."]}, {"original": "What kind of comment would you never write under someone's post, and why?", "paraphrased": "Which words would you refuse to type, even as a joke, and what makes them hurtful?", "vocab": [{"word": "comment", "definition": "A reply or opinion written under a post.", "translation": ""}, {"word": "hurtful", "definition": "Causing emotional pain to someone.", "translation": ""}], "possibleAnswers": ["I would never mock someone's appearance, because words can stay with a person for years.", "I would never share another person's secret, because trust is more important than likes.", "I would never laugh at someone's failure, because I know how that feels."]}]}, {"title": "Phones and Screen Time (12 questions)", "slug": "phonesandscreentime", "level": "A2-B1", "questions": [{"original": "Would you rather lose your phone for a week or your computer for a month?", "paraphrased": "Which device would be harder to live without, and what would you miss first?", "vocab": [{"word": "device", "definition": "A piece of equipment such as a phone, tablet or computer.", "translation": ""}, {"word": "lose", "definition": "To no longer have something because you cannot find it.", "translation": ""}], "possibleAnswers": ["I would lose my computer, because my phone is where all my friends and music live.", "I would lose my phone, because I need my computer for schoolwork.", "I would lose my phone, but only if I could still call my family from a landline."]}, {"original": "What is the best thing your phone helps you do, and what is the worst thing it has stopped you from doing?", "paraphrased": "Which daily task does your phone make easier, and which skill are you forgetting?", "vocab": [{"word": "daily", "definition": "Happening or done every day.", "translation": ""}, {"word": "skill", "definition": "An ability you learn and improve by practising.", "translation": ""}], "possibleAnswers": ["My phone helps me find information quickly, but it has stopped me from remembering phone numbers.", "My phone makes it easy to talk to friends, but I no longer read books for fun.", "My phone helps me organise my homework, but I have forgotten how to use a paper map."]}, {"original": "Do you think there should be a time limit on phone use for teenagers?", "paraphrased": "Should parents set a daily limit, or should young people decide for themselves?", "vocab": [{"word": "limit", "definition": "A point or amount you must not go past.", "translation": ""}, {"word": "decide", "definition": "To choose after thinking carefully.", "translation": ""}], "possibleAnswers": ["Yes, because too much screen time can ruin your sleep and your concentration.", "No, because teenagers should learn to manage their own time before adulthood.", "A limit is useful at night, but during the day I should be free to choose."]}, {"original": "What is your favourite app for relaxing, and what does it give you?", "paraphrased": "Which app helps you unwind after a long day, and why does it work?", "vocab": [{"word": "relax", "definition": "To rest and feel calm.", "translation": ""}, {"word": "unwind", "definition": "To relax after feeling stressed or busy.", "translation": ""}], "possibleAnswers": ["I use a music app, because my favourite songs make my shoulders drop.", "I use a drawing app, because creating something quiet helps me forget the day.", "I use a meditation app, because it teaches me to breathe slowly when I am anxious."]}, {"original": "If your phone could only do three things tomorrow, which three would you keep?", "paraphrased": "Which three functions would you save, and what would you lose forever?", "vocab": [{"word": "function", "definition": "A job that a device or app can do.", "translation": ""}, {"word": "save", "definition": "To keep something so you can use it later.", "translation": ""}], "possibleAnswers": ["I would keep messages, music and the camera, because they are the three things I use every day.", "I would keep maps, my alarm and my notes app, because school and travel would fall apart without them.", "I would keep calls, the torch and the calendar, because they are simple but essential."]}, {"original": "If you could invent a phone feature that protected your sleep, what would it do?", "paraphrased": "What smart tool would stop screens from stealing your rest?", "vocab": [{"word": "invent", "definition": "To create something new for the first time.", "translation": ""}, {"word": "protect", "definition": "To keep someone or something safe from harm.", "translation": ""}], "possibleAnswers": ["It would slowly dim the screen and play calm sounds an hour before bed.", "It would lock all apps at my chosen bedtime, except for alarms and family calls.", "It would detect when I am tired and remind me to stop, instead of letting me scroll."]}, {"original": "A friend falls asleep with their phone every night and feels tired all day. What advice would you give them?", "paraphrased": "How would you help someone break the habit of late-night scrolling?", "vocab": [{"word": "advice", "definition": "An opinion about what someone should do.", "translation": ""}, {"word": "break", "definition": "To stop a habit or pattern.", "translation": ""}], "possibleAnswers": ["I would tell them to charge the phone in another room and buy an old-fashioned alarm clock.", "I would suggest they read a book before bed instead of watching videos.", "I would tell them to set a nightly reminder that says: the phone can wait until tomorrow."]}, {"original": "When do you notice you have been looking at your screen for too long?", "paraphrased": "What sign tells you it is time to put your phone down?", "vocab": [{"word": "notice", "definition": "To see or realise something.", "translation": ""}, {"word": "sign", "definition": "A signal that something is happening.", "translation": ""}], "possibleAnswers": ["I notice when my eyes feel dry and my neck hurts.", "I notice when I have read the same post three times without understanding it.", "I notice when my mum calls me twice and I have not heard her."]}, {"original": "Phones make it easier to keep in touch with friends. Do you agree?", "paraphrased": "Has your phone brought you closer to friends, or only made you busier?", "vocab": [{"word": "easier", "definition": "Less difficult to do.", "translation": ""}, {"word": "closer", "definition": "More near in feeling or friendship.", "translation": ""}], "possibleAnswers": ["Yes, because I can message my best friend even when she is on holiday.", "Not really, because we send short messages but we rarely talk properly.", "Both: it keeps us in contact, but sometimes it replaces real meetings."]}, {"original": "Imagine your school banned phones for a whole term. What would change for you?", "paraphrased": "How would your day be different without a phone in your pocket?", "vocab": [{"word": "ban", "definition": "To officially say something is not allowed.", "translation": ""}, {"word": "different", "definition": "Not the same as before.", "translation": ""}], "possibleAnswers": ["I would talk to more people at break, because we would not be looking at screens.", "I would feel stressed at first, but I might sleep better and concentrate more.", "I would have to use paper timetables again, which would be annoying but not terrible."]}, {"original": "Would you rather read a book on paper or on a screen before bed?", "paraphrased": "Which way of reading helps you sleep better, and why?", "vocab": [{"word": "screen", "definition": "The flat surface of a phone, tablet or computer.", "translation": ""}, {"word": "sleep", "definition": "The natural state of rest your body needs at night.", "translation": ""}], "possibleAnswers": ["Paper, because the light from a screen makes my brain think it is still daytime.", "A screen, because I can make the letters bigger and read in the dark.", "Paper, because I can drop it on my face without breaking anything expensive."]}, {"original": "What is one rule about phones that you think every family should have?", "paraphrased": "Which phone habit should every household agree on?", "vocab": [{"word": "rule", "definition": "An instruction that tells you what you may or may not do.", "translation": ""}, {"word": "household", "definition": "The people who live together in one home.", "translation": ""}], "possibleAnswers": ["No phones at the dinner table, so we actually talk to each other.", "All phones go off at a certain time, so everyone sleeps well.", "Parents and children follow the same rules, because fairness makes rules easier to accept."]}]}, {"title": "Gaming (12 questions)", "slug": "gaming", "level": "A2-B1", "questions": [{"original": "Would you rather play a game alone or with a team you have never met?", "paraphrased": "Do you prefer quiet single-player worlds or noisy online teams?", "vocab": [{"word": "alone", "definition": "With no other person present.", "translation": ""}, {"word": "team", "definition": "A group of players who work together to win.", "translation": ""}], "possibleAnswers": ["I prefer playing alone, because I can pause whenever I want and enjoy the story.", "I prefer a team, because the laughs and teamwork make the game exciting.", "I like both, but only if the online team is friendly and not rude."]}, {"original": "What is your favourite video game, and what makes you want to play it again?", "paraphrased": "Which game world do you keep returning to, and what pulls you back?", "vocab": [{"word": "favourite", "definition": "The one you like most.", "translation": ""}, {"word": "return", "definition": "To go back to a place or activity.", "translation": ""}], "possibleAnswers": ["I love a racing game, because beating my own time gives me a real sense of progress.", "I love a building game, because I can create a world that nobody else has seen.", "I love a story game, because the characters feel like friends I want to visit again."]}, {"original": "What is the most frustrating part of online gaming, and what is the most exciting?", "paraphrased": "Which moment makes you want to quit, and which moment makes you feel proud?", "vocab": [{"word": "frustrating", "definition": "Making you feel annoyed or upset.", "translation": ""}, {"word": "exciting", "definition": "Making you feel eager and full of energy.", "translation": ""}], "possibleAnswers": ["The most frustrating part is losing because of a bad internet connection, and the most exciting is a last-second win.", "The most frustrating part is rude players, and the most exciting is beating a level I have tried for weeks.", "The most frustrating part is repetition, and the most exciting is discovering a secret area."]}, {"original": "If you could live inside any game for a day, which world would you choose?", "paraphrased": "Which game universe would you explore first, and what would you do there?", "vocab": [{"word": "universe", "definition": "A world with its own rules, places and creatures.", "translation": ""}, {"word": "explore", "definition": "To travel around and discover new things.", "translation": ""}], "possibleAnswers": ["I would choose a fantasy world with dragons, because flying would be unforgettable.", "I would choose a space game, because I want to see what a planet looks like from above.", "I would choose a city-building game, because I could design a place with no traffic."]}, {"original": "Do you agree that playing video games can make you a better problem solver?", "paraphrased": "Do games train your brain, or do they just fill your time?", "vocab": [{"word": "problem solver", "definition": "Someone who finds answers to difficult situations.", "translation": ""}, {"word": "train", "definition": "To teach or practise a skill.", "translation": ""}], "possibleAnswers": ["Yes, because puzzle games force you to plan several moves ahead.", "Sometimes, because strategy games help, but mindless games do not.", "No, because problem solving in a game rarely works in real life."]}, {"original": "If you could design a game about your own life, what would the main challenge be?", "paraphrased": "What level would represent your biggest struggle, and what would winning look like?", "vocab": [{"word": "design", "definition": "To plan how something will work or look.", "translation": ""}, {"word": "challenge", "definition": "Something difficult that tests your ability.", "translation": ""}], "possibleAnswers": ["The main challenge would be balancing school and friends, because both want my time.", "The main challenge would be speaking in front of the class, because I get nervous.", "The main challenge would be finding my own style, because everyone compares themselves online."]}, {"original": "A younger player is being teased in an online game. What should they do?", "paraphrased": "How would you help a friend who is being bullied in an online game?", "vocab": [{"word": "tease", "definition": "To laugh at or say unkind things to someone.", "translation": ""}, {"word": "online", "definition": "Connected to or happening on the internet.", "translation": ""}], "possibleAnswers": ["They should mute the player, block them and tell a trusted adult what happened.", "They should save the messages as proof and report the player to the game moderators.", "They should leave the match and find a kinder server, because their feelings matter more than the game."]}, {"original": "Who is the most interesting character in a game you play, and what do you like about them?", "paraphrased": "Which game character feels most real to you, and why?", "vocab": [{"word": "character", "definition": "A person or creature in a game or story.", "translation": ""}, {"word": "real", "definition": "True to life, like a real person.", "translation": ""}], "possibleAnswers": ["I like a character who makes mistakes, because it makes me feel that my own mistakes are normal.", "I like a character who is funny but brave, because humour makes hard moments easier.", "I like a character who changes during the story, because growth is interesting to watch."]}, {"original": "Would you rather win a match easily or lose a match in an exciting way?", "paraphrased": "Do you value the win more, or the story of a close game?", "vocab": [{"word": "match", "definition": "One game between players or teams.", "translation": ""}, {"word": "value", "definition": "To think something is important.", "translation": ""}], "possibleAnswers": ["I would rather win easily, because winning feels good and I do not enjoy stress.", "I would rather lose an exciting match, because close games are more fun to remember.", "I value the win, but only if I had to work hard for it."]}, {"original": "Imagine games could feel real, like stepping into a dream. Would you try one?", "paraphrased": "If you could enter a game world for an hour, would you take the risk?", "vocab": [{"word": "imagine", "definition": "To form a picture in your mind.", "translation": ""}, {"word": "risk", "definition": "The chance that something bad could happen.", "translation": ""}], "possibleAnswers": ["Yes, because feeling inside a story would be the greatest adventure of my life.", "No, because I would be afraid I could not get back to the real world.", "Yes, but only if I could leave whenever I wanted."]}, {"original": "What is one skill a good gamer needs that school does not teach?", "paraphrased": "Which personal quality matters more in games: patience, teamwork or quick thinking?", "vocab": [{"word": "skill", "definition": "An ability you develop by practising.", "translation": ""}, {"word": "patience", "definition": "The ability to wait calmly without getting angry.", "translation": ""}], "possibleAnswers": ["Patience, because some levels take many tries and giving up helps nobody.", "Teamwork, because even the best player loses without good communication.", "Quick thinking, because a split-second decision can change the whole match."]}, {"original": "Spending money on items inside a game is a waste. Do you agree?", "paraphrased": "Are in-game purchases clever, or do they trick players?", "vocab": [{"word": "purchase", "definition": "Something you buy.", "translation": ""}, {"word": "trick", "definition": "To make someone believe something that is false.", "translation": ""}], "possibleAnswers": ["Yes, because digital items disappear if the game closes, so the money buys nothing real.", "No, because supporting a game you love helps the developers make it better.", "It depends: small purchases are fine, but games that pressure children are unfair."]}]}, {"title": "Music, Films and Fandom (12 questions)", "slug": "musicfilmsfandom", "level": "A2-B1", "questions": [{"original": "What is your favourite song at the moment, and what memory does it carry?", "paraphrased": "Which track is on repeat for you, and what does it remind you of?", "vocab": [{"word": "track", "definition": "A single song on an album or playlist.", "translation": ""}, {"word": "repeat", "definition": "Playing something again and again.", "translation": ""}], "possibleAnswers": ["A song about friendship, because it reminds me of the summer I spent with my cousins.", "A song I heard on a school trip, and now it makes me smile every time.", "A song in English, because the words helped me learn the language without trying."]}, {"original": "Would you rather watch a film at the cinema or stream it at home?", "paraphrased": "Which experience do you prefer: the big screen with strangers, or your sofa with snacks?", "vocab": [{"word": "cinema", "definition": "A building where you watch films on a big screen.", "translation": ""}, {"word": "stream", "definition": "To watch or listen to something online as it plays.", "translation": ""}], "possibleAnswers": ["The cinema, because the sound and the big screen make the story feel bigger.", "At home, because I can pause for snacks and talk about the film with my family.", "The cinema for action films, but at home for slow films I want to think about."]}, {"original": "Who is a musician you would travel far to see live, and what makes their concerts special?", "paraphrased": "Which artist would you save money to see in person, and why are they worth it?", "vocab": [{"word": "musician", "definition": "A person who plays or writes music.", "translation": ""}, {"word": "live", "definition": "Performed in front of an audience, not recorded.", "translation": ""}], "possibleAnswers": ["I would travel to see a singer whose lyrics helped me through a hard year.", "I would travel to see a band known for amazing lights and energy, because a concert should feel like a party.", "I would travel to see my favourite rapper, because hearing the songs in a crowd would be unforgettable."]}, {"original": "If you could be a character in any film for a week, who would you be?", "paraphrased": "Which movie role would you try on, and what would you change about the story?", "vocab": [{"word": "character", "definition": "A person in a film, book or game.", "translation": ""}, {"word": "role", "definition": "A part someone plays in a story.", "translation": ""}], "possibleAnswers": ["I would be a young detective, because solving the mystery would be exciting.", "I would be the funny best friend, because I like making people laugh.", "I would be a character who travels through time, and I would warn people about their mistakes."]}, {"original": "Do you think it is possible to love a story too much?", "paraphrased": "Can a fandom become a problem, or is passion always a good thing?", "vocab": [{"word": "possible", "definition": "Able to happen or be true.", "translation": ""}, {"word": "passion", "definition": "A very strong interest in something.", "translation": ""}], "possibleAnswers": ["Yes, because some fans forget to sleep, study or talk to their family.", "No, because loving a story deeply can make you creative and confident.", "Only if the passion turns into anger towards people who like something else."]}, {"original": "What is the worst film you have ever watched, and what was the best part of it?", "paraphrased": "Which movie disappointed you most, and did anything save it?", "vocab": [{"word": "disappointed", "definition": "Sad because something was not as good as you hoped.", "translation": ""}, {"word": "save", "definition": "To make something less bad or ruined.", "translation": ""}], "possibleAnswers": ["A boring adventure film, but the music was so good that I stayed until the end.", "A film with a great idea and a terrible ending, which made me angry for days.", "A comedy with no funny moments, but my friends made it fun because we laughed at it."]}, {"original": "A friend says your favourite band is boring. How do you answer without starting an argument?", "paraphrased": "How would you defend your taste while still respecting theirs?", "vocab": [{"word": "defend", "definition": "To say why you think something is good.", "translation": ""}, {"word": "taste", "definition": "The kind of things you like.", "translation": ""}], "possibleAnswers": ["I would say that taste is personal, and ask them what music they love instead.", "I would explain why the lyrics matter to me, and then listen to their favourite song.", "I would laugh and say we can both be right, because music is big enough for everyone."]}, {"original": "If you could ask a director one question about their film, what would it be?", "paraphrased": "What secret about a movie would you want the person who made it to explain?", "vocab": [{"word": "director", "definition": "The person in charge of making a film.", "translation": ""}, {"word": "explain", "definition": "To make something clear so people understand it.", "translation": ""}], "possibleAnswers": ["I would ask why they chose that ending, because it confused me.", "I would ask how they found the actor, because the performance felt so real.", "I would ask what scene they almost removed, because it is my favourite."]}, {"original": "What is one song you would play to cheer up a friend who is having a bad day?", "paraphrased": "Which track always changes your mood, and why does it work?", "vocab": [{"word": "cheer up", "definition": "To make someone feel happier.", "translation": ""}, {"word": "mood", "definition": "The way you feel at a particular time.", "translation": ""}], "possibleAnswers": ["A silly, fast song, because laughing is the quickest way to feel better.", "A calm song with kind words, because it tells my friend they are not alone.", "An old song we both love, because shared memories make hard days easier."]}, {"original": "Would you rather read the book first or watch the film first?", "paraphrased": "Which version do you like discovering first, and does it ruin the other?", "vocab": [{"word": "version", "definition": "One form of the same story.", "translation": ""}, {"word": "ruin", "definition": "To spoil or damage something.", "translation": ""}], "possibleAnswers": ["The book first, because my imagination makes better pictures than any film.", "The film first, because reading afterwards lets me add my own details.", "The book first, because films almost always leave out my favourite parts."]}, {"original": "Imagine your favourite band breaks up tomorrow. How would you remember them?", "paraphrased": "If the music stopped forever, what would you keep to hold onto the feeling?", "vocab": [{"word": "break up", "definition": "To stop being a group or a band.", "translation": ""}, {"word": "hold onto", "definition": "To keep something safely in your life.", "translation": ""}], "possibleAnswers": ["I would keep their songs on a special playlist and play them when I need courage.", "I would keep the concert ticket, because it reminds me of one of the best nights of my life.", "I would keep the lyrics I wrote in my notebook, because they taught me how to express myself."]}, {"original": "What is one thing a fandom does that helps people feel they belong?", "paraphrased": "Which fan community activity makes newcomers feel welcome?", "vocab": [{"word": "fandom", "definition": "A group of fans who share a strong interest.", "translation": ""}, {"word": "welcome", "definition": "To make someone feel they belong.", "translation": ""}], "possibleAnswers": ["Fan art and friendly comments, because a new person sees that their voice is wanted.", "Group watch parties, because laughing together makes strangers feel like friends.", "Helping new fans find the best stories, because kindness is the best welcome."]}]}, {"title": "AI and the Internet (12 questions)", "slug": "aiandinternet", "level": "A2-B1", "questions": [{"original": "Would you rather ask an AI for help with homework or ask a teacher?", "paraphrased": "Which helper do you trust more, and when would you choose the other?", "vocab": [{"word": "homework", "definition": "Work set by school to do at home.", "translation": ""}, {"word": "trust", "definition": "To believe someone is honest and reliable.", "translation": ""}], "possibleAnswers": ["I would ask a teacher, because they can explain why an answer is right, not just give the answer.", "I would ask AI first for a quick explanation, then check it with my teacher.", "I would ask AI for practice questions, but a teacher for help with my confidence."]}, {"original": "If an AI could do one of your school tasks perfectly, which one would you give it?", "paraphrased": "Which chore or assignment would you hand over, and what would you do with the free time?", "vocab": [{"word": "task", "definition": "A piece of work you must finish.", "translation": ""}, {"word": "assignment", "definition": "A task given to you by a teacher.", "translation": ""}], "possibleAnswers": ["I would give it my repetitive spelling exercises, because they take time and teach me little.", "I would give it my timetable planning, because I would rather spend that time on art.", "I would keep everything, because the struggle is how I learn."]}, {"original": "Do you think AI will change the jobs people do in the future?", "paraphrased": "Which careers do you think machines will take over, and which will stay human?", "vocab": [{"word": "career", "definition": "The job or profession you do for many years.", "translation": ""}, {"word": "human", "definition": "A person, not a machine.", "translation": ""}], "possibleAnswers": ["Yes, machines will take over boring repetitive work, but jobs that need care will stay human.", "Yes, and I think we will need new rules so people are not left without work.", "No, because humans are creative and machines only copy what already exists."]}, {"original": "What is the most useful thing you have learned from the internet this year?", "paraphrased": "Which skill or idea did you pick up online, and how did you use it?", "vocab": [{"word": "useful", "definition": "Helpful for a purpose.", "translation": ""}, {"word": "skill", "definition": "An ability you learn by practising.", "translation": ""}], "possibleAnswers": ["I learned how to edit videos, and I used it for a school project about my town.", "I learned basic first aid from a trusted site, and it helped when my brother cut his finger.", "I learned how to manage my time better, and it made my homework evenings calmer."]}, {"original": "If you could teach an AI one thing about being a good friend, what would it be?", "paraphrased": "What human quality should a machine never forget?", "vocab": [{"word": "quality", "definition": "A characteristic or feature of a person.", "translation": ""}, {"word": "machine", "definition": "A device that does work, like a computer.", "translation": ""}], "possibleAnswers": ["I would teach it to listen before it answers, because good friends do not interrupt.", "I would teach it to remember small details, because that shows you care.", "I would teach it to admit when it is wrong, because honesty builds trust."]}, {"original": "What is the scariest thing about the internet, and what is the most hopeful?", "paraphrased": "Which online danger worries you, and which online change gives you hope?", "vocab": [{"word": "scariest", "definition": "Most frightening.", "translation": ""}, {"word": "hopeful", "definition": "Feeling that good things will happen.", "translation": ""}], "possibleAnswers": ["The scariest thing is strangers pretending to be friends, and the most hopeful is how quickly people help each other.", "The scariest thing is fake news, and the most hopeful is free lessons from good teachers.", "The scariest thing is losing privacy, and the most hopeful is young people who speak up for change."]}, {"original": "A classmate uses AI to write an essay and pretends it is theirs. What would you say to them?", "paraphrased": "How would you explain why copying AI work is unfair?", "vocab": [{"word": "essay", "definition": "A piece of writing about a subject, often for school.", "translation": ""}, {"word": "unfair", "definition": "Not equal or just.", "translation": ""}], "possibleAnswers": ["I would say that the teacher wants to see their thinking, not a machine's, and cheating hurts them too.", "I would say that copying is unfair to classmates who did the work honestly.", "I would suggest they use AI to plan the essay, but write it themselves."]}, {"original": "When do you check if something you read online is true?", "paraphrased": "What makes you stop and double-check a strange fact?", "vocab": [{"word": "check", "definition": "To look at something carefully to be sure.", "translation": ""}, {"word": "fact", "definition": "A piece of information that is true.", "translation": ""}], "possibleAnswers": ["I check when a story sounds too shocking or too perfect to be real.", "I check before I share anything, because my friends trust me.", "I check when two websites say different things, and then I look for a trusted source."]}, {"original": "Imagine the internet disappeared for one month. What would you miss most?", "paraphrased": "Which online habit would be hardest to give up, and what would fill the gap?", "vocab": [{"word": "disappear", "definition": "To stop existing or being visible.", "translation": ""}, {"word": "gap", "definition": "An empty space or missing part.", "translation": ""}], "possibleAnswers": ["I would miss video calls with my cousin abroad, but we would write letters instead.", "I would miss searching for answers, but the library would become my new best friend.", "I would miss music streaming, but I would finally learn to play the guitar."]}, {"original": "Children should learn about AI at school before they learn to code. Do you agree?", "paraphrased": "Is understanding AI more important than writing computer programs?", "vocab": [{"word": "code", "definition": "Instructions written for a computer to follow.", "translation": ""}, {"word": "understand", "definition": "To know what something means.", "translation": ""}], "possibleAnswers": ["Yes, because everyone uses AI now, but not everyone needs to be a programmer.", "No, because coding teaches logical thinking that helps you understand AI too.", "Both matter, but AI literacy should come first so children use it safely."]}, {"original": "Would you rather have an AI that remembers everything you like, or one that forgets your mistakes?", "paraphrased": "Which is better: a machine that knows your taste, or one that forgives your errors?", "vocab": [{"word": "remember", "definition": "To keep something in your memory.", "translation": ""}, {"word": "forgive", "definition": "To stop being angry with someone for a mistake.", "translation": ""}], "possibleAnswers": ["An AI that remembers my taste, because it could recommend music and books I would love.", "An AI that forgets my mistakes, because nobody should be punished forever for being young.", "Neither, because I want a machine that is honest, not one that only flatters me."]}, {"original": "What is one question you would ask an AI that you would never ask a person?", "paraphrased": "Which secret or embarrassing thought would you only share with a machine?", "vocab": [{"word": "embarrassing", "definition": "Making you feel shy or awkward.", "translation": ""}, {"word": "secret", "definition": "Something you keep to yourself.", "translation": ""}], "possibleAnswers": ["I would ask if my friends secretly find me annoying, because I could not ask them.", "I would ask for help with a problem I am too shy to discuss with a teacher.", "I would ask what my future might look like, even though I know a machine cannot really know."]}]}]}, {"category": "Family and Feelings", "topics": [{"title": "Family Life (12 questions)", "slug": "familylife", "level": "A2-B1", "questions": [{"original": "If you could design a brand-new family tradition that your whole family would do every year, what would it be?", "paraphrased": "What special yearly event would you invent, and who in your family would enjoy it most?", "vocab": [{"word": "tradition", "definition": "A custom or habit that a family does again and again, often at the same time each year.", "translation": ""}, {"word": "invent", "definition": "To create something new that did not exist before.", "translation": ""}], "possibleAnswers": ["I would invent a 'story night' where everyone tells a made-up tale about our family, because my little brother loves silly stories.", "I would make a summer camping weekend with just us and no phones. It would be simple and fun.", "I would choose a yearly 'switch day' where parents and children swap roles for one day."]}, {"original": "Would you rather have a big family dinner every Sunday or a small family trip once a month?", "paraphrased": "Which do you value more: regular time together at home or occasional adventures out?", "vocab": [{"word": "value", "definition": "To think that something is important and worth having.", "translation": ""}, {"word": "occasional", "definition": "Happening sometimes, but not often or regularly.", "translation": ""}], "possibleAnswers": ["I would rather have the Sunday dinner. It feels warm and it is easier to talk when you are relaxed.", "I prefer the monthly trip, because we always come home with a new story.", "Honestly I would choose both, but if I must pick, the trip wins."]}, {"original": "What is your favourite memory with your family, and why does it still make you smile?", "paraphrased": "Which family moment do you replay in your mind, and what makes it so warm?", "vocab": [{"word": "memory", "definition": "Something you remember from the past, like a picture in your mind.", "translation": ""}, {"word": "replay", "definition": "To think about something again, as if you were watching it a second time.", "translation": ""}], "possibleAnswers": ["The time we all got lost on a walk and ended up at a tiny café. We laughed about it for weeks.", "My favourite memory is cooking with my gran. She lets me taste everything and tells funny stories.", "It was a normal evening when my dad danced in the kitchen. It was so silly that we still laugh."]}, {"original": "What is the worst part about family meals, and what is the best part?", "paraphrased": "Which moment at the dinner table do you enjoy least, and which do you enjoy most?", "vocab": [{"word": "worst", "definition": "The most unpleasant or difficult part of something.", "translation": ""}, {"word": "enjoy", "definition": "To like something and feel happy while you do it.", "translation": ""}], "possibleAnswers": ["The worst part is when my brother talks with his mouth full. The best part is dessert, obviously.", "I do not like when adults ask about school grades. I love it when we tell jokes.", "The worst is washing up afterwards, but the best is hearing about everyone's day."]}, {"original": "If you could give your family one superpower for a day, what would it be and how would you use it?", "paraphrased": "What ability would change your family life for 24 hours, and what would you do together?", "vocab": [{"word": "superpower", "definition": "An imaginary ability that is stronger than normal, like flying or reading minds.", "translation": ""}, {"word": "ability", "definition": "The power or skill to do something.", "translation": ""}], "possibleAnswers": ["I would give us the ability to clean the whole house in one minute, so we could spend the day outside.", "I would choose flying. We could visit the mountains and be home for dinner.", "I would pick mind-reading, just to find out what my sister is really thinking."]}, {"original": "Who in your family makes you laugh the most, and what do they do?", "paraphrased": "Which person at home is the funniest, and what is your favourite thing they say?", "vocab": [{"word": "funniest", "definition": "The person who makes you laugh more than anyone else.", "translation": ""}, {"word": "favourite", "definition": "The person or thing you like the most.", "translation": ""}], "possibleAnswers": ["My uncle tells terrible jokes, but he tells them so seriously that I cannot stop laughing.", "My little sister is the funniest. She copies my dad's angry face perfectly.", "My mum makes me laugh when she pretends not to understand her phone."]}, {"original": "Agree or disagree: teenagers should choose what their family eats for dinner once a week.", "paraphrased": "Should young people have a real say in family food decisions? Why or why not?", "vocab": [{"word": "agree", "definition": "To have the same opinion as someone, or to say yes to an idea.", "translation": ""}, {"word": "decide", "definition": "To choose one thing after thinking about the options.", "translation": ""}], "possibleAnswers": ["I agree, because then we would finally get food we actually like.", "I disagree, because teenagers might only choose pizza and chips every week.", "I agree, but only if the young person also helps to cook it."]}, {"original": "What advice would you give to someone whose family has just moved to a new country?", "paraphrased": "How would you help a new classmate settle into an unfamiliar place and school?", "vocab": [{"word": "advice", "definition": "Helpful words that tell someone what you think they should do.", "translation": ""}, {"word": "settle", "definition": "To feel comfortable and at home in a new place.", "translation": ""}], "possibleAnswers": ["I would tell them to be patient and to join one club. Friends usually come from doing things together.", "I would say: do not hide your language or food. People are curious, and that is a good start.", "I would help them find the quiet places in school, so the first week feels less busy."]}, {"original": "If your family had a pet that could talk, what would you want it to say first?", "paraphrased": "What secret about your home would you love a talking pet to share?", "vocab": [{"word": "pet", "definition": "An animal that lives with you and is part of your family, like a dog or cat.", "translation": ""}, {"word": "secret", "definition": "Something you know but do not tell other people.", "translation": ""}], "possibleAnswers": ["I would want it to tell me where it hides my missing socks.", "I would ask who really ate the cake that disappeared last weekend.", "I would love it to say how much it enjoys our quiet evenings together."]}, {"original": "What was the last thing your family did together that made you feel proud?", "paraphrased": "Which recent family achievement or kind act still makes you feel good?", "vocab": [{"word": "proud", "definition": "Feeling happy and pleased about something you or someone you love has done.", "translation": ""}, {"word": "achievement", "definition": "Something difficult that you have managed to do successfully.", "translation": ""}], "possibleAnswers": ["We helped my grandma move her heavy boxes, and she cried a little. It felt really good.", "My sister passed her swimming test and we all cheered so loudly.", "We cooked a big meal for a neighbour who was ill. It was small, but it mattered."]}, {"original": "Imagine your family is a band. What instrument would each person play, and why?", "paraphrased": "If each relative had a musical role, who would be the singer, the drummer, and the quiet listener?", "vocab": [{"word": "instrument", "definition": "An object you play to make music, such as a guitar or drum.", "translation": ""}, {"word": "relative", "definition": "A person in your family, like a parent, aunt, cousin or grandparent.", "translation": ""}], "possibleAnswers": ["My dad would be the drummer because he is loud and always in a hurry.", "My mum would sing, and my brother would play the keyboard badly but with great confidence.", "My grandma would play the violin slowly, and I would be the quiet one tuning everything."]}, {"original": "What is one photo of your family that you would save forever, and what story does it tell?", "paraphrased": "Which picture captures your family best, and what happened just before it was taken?", "vocab": [{"word": "photo", "definition": "A picture taken with a camera or phone.", "translation": ""}, {"word": "forever", "definition": "For all time, without an end.", "translation": ""}], "possibleAnswers": ["The one from the beach where everyone is laughing with wet hair. Just before it, my brother fell in the sea.", "A photo of my whole family at my aunt's wedding. I like it because we all look relaxed.", "The picture of my gran holding my new baby cousin. It shows four generations in one frame."]}]}, {"title": "Friendships and Falling Out (12 questions)", "slug": "friendshipsfallingout", "level": "A2-B1", "questions": [{"original": "Would you rather have one best friend or five good friends?", "paraphrased": "Do you prefer deep time with a single friend, or variety across a bigger group?", "vocab": [{"word": "rather", "definition": "Used to say which of two things you would choose.", "translation": ""}, {"word": "variety", "definition": "Having many different people or things, instead of just one.", "translation": ""}], "possibleAnswers": ["I would rather have one best friend. It is better to be understood by one person than liked by many.", "I prefer five good friends, because there is always someone to message.", "It depends on the day. Sometimes I want a crowd, and sometimes I want one person."]}, {"original": "What makes a friend trustworthy, and can trust be repaired after a lie?", "paraphrased": "Which qualities show a friend is reliable, and is it possible to rebuild trust?", "vocab": [{"word": "trustworthy", "definition": "A person you can trust because they do what they say.", "translation": ""}, {"word": "reliable", "definition": "Always behaving in the same good way, so people can depend on you.", "translation": ""}], "possibleAnswers": ["Keeping secrets makes a friend trustworthy. Trust can come back, but it takes a long time.", "I think honesty is the most important thing. A lie hurts, but a true apology can help.", "Being there when things are hard matters most. Trust is rebuilt by small actions, not words."]}, {"original": "If you and your best friend fell out over something silly, who would you want to say sorry first?", "paraphrased": "After a small argument, would you rather apologise first or wait for the other person?", "vocab": [{"word": "fell out", "definition": "To stop being friendly with someone after an argument.", "translation": ""}, {"word": "apologise", "definition": "To say sorry for something you did wrong.", "translation": ""}], "possibleAnswers": ["I would apologise first. Being friends is more important than being right.", "I would wait, because I do not like arguing and I hope they miss me too.", "I would send a funny message first, and then say sorry properly."]}, {"original": "What is the kindest thing a friend has ever done for you?", "paraphrased": "Which small act of friendship stayed with you the longest?", "vocab": [{"word": "kindest", "definition": "The most caring and gentle thing someone has done.", "translation": ""}, {"word": "act", "definition": "A thing that someone does, especially something helpful or kind.", "translation": ""}], "possibleAnswers": ["My friend walked home with me when I was upset, even though it made her late.", "She shared her notes when I was ill, and she wrote them neatly so I could read them.", "He sat with me at lunch when nobody else did. I still remember that."]}, {"original": "Agree or disagree: it is better to end a friendship quietly than to have a big argument.", "paraphrased": "Should you walk away from a toxic friend without explaining, or talk it through?", "vocab": [{"word": "agree", "definition": "To say yes to an idea because you think it is right.", "translation": ""}, {"word": "toxic", "definition": "A relationship that makes you feel bad, anxious or small.", "translation": ""}], "possibleAnswers": ["I disagree. Even if it is uncomfortable, a honest conversation gives both people closure.", "I agree, because some arguments only make things worse and nobody really wins.", "It depends. If the person is dangerous or cruel, it is safer to leave quietly."]}, {"original": "What advice would you give to someone who feels left out at lunchtime?", "paraphrased": "How would you help a classmate who eats alone and wants to join in?", "vocab": [{"word": "advice", "definition": "Useful suggestions about what someone should do.", "translation": ""}, {"word": "left out", "definition": "Not included in a group or activity, in a way that feels unfair.", "translation": ""}], "possibleAnswers": ["I would say: start small. Ask one person if you can sit with them, and do not worry about the rest.", "Join a club you like. It is easier to make friends when you share something.", "I would tell them that lunch is only half an hour, and real friends often appear later."]}, {"original": "Describe your ideal day with a friend. Where would you go and what would you talk about?", "paraphrased": "If money and time were no problem, how would you and a close friend spend a perfect day?", "vocab": [{"word": "ideal", "definition": "Perfect, or exactly what you would want it to be.", "translation": ""}, {"word": "close", "definition": "A friend you know very well and trust with your feelings.", "translation": ""}], "possibleAnswers": ["We would go to the coast, eat fish and chips, and talk about our dreams until it gets dark.", "I would stay at home, bake something messy, and talk about everything and nothing.", "We would visit a big city, get lost on purpose, and make up stories about the people we see."]}, {"original": "Who was your first friend, and what do you remember about playing together?", "paraphrased": "What is your earliest friendship memory, and what game did you love?", "vocab": [{"word": "earliest", "definition": "The one that happened first or a long time ago.", "translation": ""}, {"word": "memory", "definition": "Something you remember from when you were younger.", "translation": ""}], "possibleAnswers": ["My first friend lived next door. We played with toy cars for hours and never argued.", "I remember building a den in the garden with a girl from my class. We felt very grown up.", "We loved playing shops. She always let me be the customer, which was a kind thing to do."]}, {"original": "If you could send a message to a friend you have lost touch with, what would it say?", "paraphrased": "What would you tell an old friend you miss, and why did you drift apart?", "vocab": [{"word": "message", "definition": "Words you send to someone, for example by text or email.", "translation": ""}, {"word": "drift apart", "definition": "To slowly become less close to someone over time.", "translation": ""}], "possibleAnswers": ["I would say: I hope you are well, and I still laugh about that day at the zoo.", "I would ask if they want to meet for a coffee, because life just got busy.", "I would thank them for being kind to me when I was new at school."]}, {"original": "What is worse: a friend who copies you, or a friend who forgets your birthday?", "paraphrased": "Which hurts more — being copied by someone, or being forgotten on a special day?", "vocab": [{"word": "worse", "definition": "More unpleasant or more painful than the other choice.", "translation": ""}, {"word": "forgotten", "definition": "When someone does not remember something important.", "translation": ""}], "possibleAnswers": ["Being copied is worse, because it feels like they do not like the real me.", "Forgetting my birthday hurts more, because it shows I was not in their thoughts.", "Both are bad, but I would rather be copied than forgotten."]}, {"original": "Imagine you could invent a friendship app. What would it help people do?", "paraphrased": "What feature would make it easier to stay in touch and plan real meet-ups?", "vocab": [{"word": "invent", "definition": "To design and create something that did not exist before.", "translation": ""}, {"word": "feature", "definition": "A useful part or tool inside an app or machine.", "translation": ""}], "possibleAnswers": ["It would gently remind you to message a friend you have not seen for a while.", "It would suggest free things to do near you, so planning a meet-up is easy.", "It would let friends share a small kindness challenge each week."]}, {"original": "When a friend is upset, do you try to fix the problem or just listen? Why?", "paraphrased": "Which helps more when someone is sad: advice, or quiet company?", "vocab": [{"word": "upset", "definition": "Feeling sad, worried or unhappy about something.", "translation": ""}, {"word": "company", "definition": "Being with someone so they do not feel alone.", "translation": ""}], "possibleAnswers": ["I listen first. Most people want to be heard before they want a solution.", "I try to fix it, because I hate seeing people I love in pain.", "I do both: I listen, and then I ask if they want help."]}]}, {"title": "Feelings and Confidence (12 questions)", "slug": "feelingsconfidence", "level": "A2-B1", "questions": [{"original": "What makes you feel nervous, and what helps you calm down?", "paraphrased": "Which situations raise your anxiety, and what routine steadies you?", "vocab": [{"word": "nervous", "definition": "Feeling worried or slightly afraid before something happens.", "translation": ""}, {"word": "anxiety", "definition": "A feeling of worry or fear that can make your heart beat faster.", "translation": ""}], "possibleAnswers": ["Speaking in front of the class makes me nervous. Slow breathing helps me calm down.", "I feel nervous before exams. I listen to music and it steadies me.", "Meeting new people is hard for me. I remind myself that nobody is judging me."]}, {"original": "Would you rather give a short speech to your class or sing a song in front of them?", "paraphrased": "Which kind of performance frightens you less, and why?", "vocab": [{"word": "rather", "definition": "Used to say which of two options you prefer.", "translation": ""}, {"word": "performance", "definition": "Singing, acting or speaking in front of an audience.", "translation": ""}], "possibleAnswers": ["I would rather sing, because I can hide my nerves behind the music.", "A short speech is easier for me. I like explaining ideas clearly.", "Neither, honestly. I would try to find a way to do both badly and laugh about it."]}, {"original": "What is something you were once scared of that you can now do easily?", "paraphrased": "Which fear have you already beaten, and how did you manage it?", "vocab": [{"word": "scared", "definition": "Feeling afraid of something.", "translation": ""}, {"word": "fear", "definition": "A strong feeling of being frightened by something.", "translation": ""}], "possibleAnswers": ["I used to be scared of swimming in deep water. I practised little by little until it felt normal.", "I was afraid of the dark as a child. Now I sleep fine with a small lamp.", "I feared speaking in class. I started by answering one question a week."]}, {"original": "If your confidence was a weather forecast, what would it be today?", "paraphrased": "Describe your self-belief right now as sunny, cloudy, or stormy — and why?", "vocab": [{"word": "confidence", "definition": "Believing in yourself and your abilities.", "translation": ""}, {"word": "forecast", "definition": "A report that tells you what the weather will be like.", "translation": ""}], "possibleAnswers": ["Sunny with a few clouds. I feel good about school, but I worry a little about my grades.", "Mostly cloudy. I am not sure what I am good at at the moment.", "Stormy, but clearing up. I had a hard week, and I am slowly feeling stronger."]}, {"original": "Agree or disagree: it is okay to feel jealous sometimes, as long as you do not hurt anyone.", "paraphrased": "Is jealousy a normal feeling we should talk about, or something to hide?", "vocab": [{"word": "agree", "definition": "To think an idea is right and say yes to it.", "translation": ""}, {"word": "jealous", "definition": "Feeling upset because someone has something you wish you had.", "translation": ""}], "possibleAnswers": ["I agree. Jealousy is normal, but it should not turn into unkind words.", "I disagree, because jealousy only makes you unhappy and changes nothing.", "I agree, as long as you use it to work harder instead of blaming others."]}, {"original": "What advice would you give to a friend who keeps saying 'I am rubbish at everything'?", "paraphrased": "How would you gently help someone who is being too hard on themselves?", "vocab": [{"word": "advice", "definition": "Helpful words that guide someone about what to do.", "translation": ""}, {"word": "gently", "definition": "In a soft, careful and kind way.", "translation": ""}], "possibleAnswers": ["I would remind them of one thing they are good at, and tell them everyone struggles sometimes.", "I would say: talk to someone you trust, because those thoughts grow in the dark.", "I would sit with them and listen, without trying to fix everything straight away."]}, {"original": "Describe a time you felt really proud of yourself. What had you done?", "paraphrased": "Which personal achievement still gives you a warm feeling when you remember it?", "vocab": [{"word": "proud", "definition": "Feeling pleased and satisfied about something you have done well.", "translation": ""}, {"word": "achievement", "definition": "Something you worked for and managed to do successfully.", "translation": ""}], "possibleAnswers": ["I felt proud when I finally learned to ride a bike. I fell many times, but I kept trying.", "I helped my little sister read her first book. Her smile made me feel great.", "I passed my music exam after months of practice. It taught me that effort works."]}, {"original": "Who in your life makes you feel calm and safe, and what do they do?", "paraphrased": "Which person helps your worries disappear, and how?", "vocab": [{"word": "calm", "definition": "Peaceful and quiet, without worry or excitement.", "translation": ""}, {"word": "worries", "definition": "Thoughts that make you feel anxious about things that might go wrong.", "translation": ""}], "possibleAnswers": ["My gran makes me feel calm. She listens without interrupting and makes tea.", "My best friend makes me feel safe because I can tell her anything.", "My dog helps. He sits next to me and everything feels less serious."]}, {"original": "If you could bottle one feeling and keep it forever, which would you choose?", "paraphrased": "Which emotion would you most like to carry with you always?", "vocab": [{"word": "bottle", "definition": "To put something in a small container and keep it safe.", "translation": ""}, {"word": "emotion", "definition": "A strong feeling such as happiness, fear or sadness.", "translation": ""}], "possibleAnswers": ["I would choose happiness, because it makes hard days easier.", "I would keep excitement. It gives you energy to try new things.", "I would choose calm, because I sometimes feel too much at once."]}, {"original": "What is the best way to cheer yourself up on a rainy, boring day?", "paraphrased": "Which small habit lifts your mood when everything feels flat?", "vocab": [{"word": "cheer up", "definition": "To become happier, or to make someone else happier.", "translation": ""}, {"word": "mood", "definition": "The way you feel at a particular time, such as happy or grumpy.", "translation": ""}], "possibleAnswers": ["I put on my favourite playlist and dance badly in my room. It always works.", "I cook something simple, like pancakes. The smell makes the house feel warm.", "I message a friend. Even a short chat can change my whole mood."]}, {"original": "Imagine you had to teach your class about feelings. What would your first lesson be?", "paraphrased": "What simple skill would you show teenagers to understand their emotions better?", "vocab": [{"word": "teach", "definition": "To help someone learn a skill or understand something.", "translation": ""}, {"word": "emotions", "definition": "Strong feelings such as joy, anger, fear and love.", "translation": ""}], "possibleAnswers": ["I would teach them to name their feelings. If you can name it, it is easier to handle.", "I would show them how to breathe slowly when they are angry or anxious.", "I would teach that all feelings are normal, even the uncomfortable ones."]}, {"original": "When do you feel most like yourself — alone, with family, or with friends?", "paraphrased": "In which situation do you relax and stop trying to impress anyone?", "vocab": [{"word": "myself", "definition": "The real you, not the version you show to others.", "translation": ""}, {"word": "impress", "definition": "To try to make other people admire you.", "translation": ""}], "possibleAnswers": ["I feel most like myself alone. I can think, and I do not have to perform.", "With my closest friends. They know my weird sense of humour.", "With my family at home, especially when we cook together."]}]}, {"title": "Siblings and Rules at Home (12 questions)", "slug": "siblingshomerules", "level": "A2-B1", "questions": [{"original": "Do you have any brothers or sisters? What do you like most about them, and what annoys you?", "paraphrased": "Which sibling habit drives you mad, and which one makes you laugh?", "vocab": [{"word": "siblings", "definition": "Brothers and sisters in the same family.", "translation": ""}, {"word": "annoys", "definition": "Makes you feel a little angry or irritated.", "translation": ""}], "possibleAnswers": ["I have an older brother. He is funny, but he always takes my charger without asking.", "I have a twin sister. I like that she understands me, but she copies my clothes.", "I am an only child, so I do not have this problem — but I sometimes wish I did."]}, {"original": "Would you rather share a bedroom with a sibling or have your own room?", "paraphrased": "Which would you pick: company at night, or privacy and quiet?", "vocab": [{"word": "rather", "definition": "Used to say which of two options you would choose.", "translation": ""}, {"word": "privacy", "definition": "Time and space that belongs only to you, with no one else there.", "translation": ""}], "possibleAnswers": ["I would rather have my own room. I need quiet to read and think.", "Sharing is fine for me. It is less lonely, and we talk before sleep.", "I would choose my own room, but I would leave the door open so my sibling can visit."]}, {"original": "What house rule do you think is fair, and which one do you think is unfair?", "paraphrased": "Which family rule makes sense to you, and which one would you change?", "vocab": [{"word": "fair", "definition": "Treating everyone in a sensible and equal way.", "translation": ""}, {"word": "change", "definition": "To make something different from how it was before.", "translation": ""}], "possibleAnswers": ["A fair rule is no phones at dinner. An unfair one is going to bed before my older sister.", "I think a weekly chore rota is fair. It is unfair when parents check my messages.", "Fair: tell someone where you are. Unfair: no friends over on school nights."]}, {"original": "If you were in charge of screen time for one week, what rules would you make?", "paraphrased": "How would you limit phones and games if you were the parent for seven days?", "vocab": [{"word": "in charge", "definition": "Being the person who controls a situation and makes decisions.", "translation": ""}, {"word": "limit", "definition": "A rule about the maximum amount of something you can have.", "translation": ""}], "possibleAnswers": ["I would allow two hours of games, but no screens in the bedroom after nine.", "I would make a family rule: phones in one basket at dinner for everyone, including adults.", "I would let people choose their own limits, but no screens during homework."]}, {"original": "What is the best thing about being the oldest, the youngest, or the only child?", "paraphrased": "Which position in the family has the nicest advantages, and why?", "vocab": [{"word": "oldest", "definition": "The child who was born first and is the biggest in age.", "translation": ""}, {"word": "advantages", "definition": "Good things or benefits that make a situation easier.", "translation": ""}], "possibleAnswers": ["Being the oldest means more freedom, but also more responsibility.", "The youngest gets away with everything and has older siblings to help them.", "Only children get quiet and their own space, but they miss having built-in friends."]}, {"original": "Agree or disagree: siblings should never tell your secrets to your parents.", "paraphrased": "Is it ever right for a brother or sister to break your confidence?", "vocab": [{"word": "agree", "definition": "To think an idea is correct and support it.", "translation": ""}, {"word": "secrets", "definition": "Private information you ask someone not to share.", "translation": ""}], "possibleAnswers": ["I disagree. If someone is in danger, telling an adult is more important than keeping a secret.", "I agree. Trust between siblings is special, and breaking it hurts a lot.", "It depends on the secret. Small things should stay private, but serious problems need help."]}, {"original": "What advice would you give to a sibling who always borrows your things without asking?", "paraphrased": "How would you ask a brother or sister to respect your belongings?", "vocab": [{"word": "advice", "definition": "Helpful suggestions about what someone should do.", "translation": ""}, {"word": "respect", "definition": "To treat someone or their things with care and consideration.", "translation": ""}], "possibleAnswers": ["I would say calmly: 'Please ask first. I do not mind lending, but I mind when you take.'", "I would keep my special things in a box with a lock, and share the rest freely.", "I would borrow something of theirs without asking, so they understand how it feels."]}, {"original": "Describe the perfect Saturday at home with your family. What happens from morning to night?", "paraphrased": "If you planned a whole lazy day at home, who would be there and what would you do?", "vocab": [{"word": "perfect", "definition": "Exactly right and as good as it can possibly be.", "translation": ""}, {"word": "lazy", "definition": "Relaxed and without much activity or effort.", "translation": ""}], "possibleAnswers": ["Slow breakfast, then a walk with the dog, then a film in the afternoon with snacks.", "I would bake with my mum, play board games with my brother, and end with a takeaway.", "Everyone would do their own thing quietly, then we would cook dinner together."]}, {"original": "Who usually decides what your family watches on TV, and is that fair?", "paraphrased": "Which person controls the remote, and do you get a proper turn?", "vocab": [{"word": "decides", "definition": "Chooses one option after thinking about it.", "translation": ""}, {"word": "remote", "definition": "The small device you use to change channels and volume on the television.", "translation": ""}], "possibleAnswers": ["My dad decides, and honestly it is fair because he lets us pick on weekends.", "My little sister always grabs the remote. It is annoying but she is the youngest.", "We take turns. It is fair, but we argue about whose turn it is."]}, {"original": "If you could swap one chore for something more fun, what would you choose?", "paraphrased": "Which household task would you happily trade, and what would you do instead?", "vocab": [{"word": "swap", "definition": "To exchange one thing for another.", "translation": ""}, {"word": "chore", "definition": "A small regular job around the house, such as washing up or tidying.", "translation": ""}], "possibleAnswers": ["I would swap washing up for cooking, because I like making things more than cleaning.", "I would swap tidying my room for walking the dog. Fresh air is better than folding clothes.", "I would swap hoovering for watering the plants. It is calmer and quieter."]}, {"original": "Imagine your sibling could read your mind for one day. What would you hide?", "paraphrased": "Which thought would you keep private if your brother or sister could hear it?", "vocab": [{"word": "imagine", "definition": "To picture something in your mind that is not real.", "translation": ""}, {"word": "private", "definition": "Belonging only to you and not meant to be shared with others.", "translation": ""}], "possibleAnswers": ["I would hide the thoughts where I am a little jealous of them.", "I would hide my plans for their birthday surprise.", "I would hide the times I pretend not to hear when they call me."]}, {"original": "What is one rule your parents have that you hope you keep when you have your own family?", "paraphrased": "Which family habit would you pass on to your future children, and why?", "vocab": [{"word": "rule", "definition": "A clear instruction about what is allowed and what is not.", "translation": ""}, {"word": "habit", "definition": "Something you do regularly, often without thinking about it.", "translation": ""}], "possibleAnswers": ["My parents always eat dinner together. I hope I keep that, because it keeps us close.", "They say sorry when they are wrong. I want to do the same with my children.", "They let us make mistakes. I hope I can be that calm with my own kids."]}]}, {"title": "Kindness and Bullying (12 questions)", "slug": "kindnessbullying", "level": "A2-B1", "questions": [{"original": "What small act of kindness has someone done for you that you still remember?", "paraphrased": "Which tiny good deed surprised you, and how did it change your day?", "vocab": [{"word": "act", "definition": "A thing someone does, especially something helpful or kind.", "translation": ""}, {"word": "deed", "definition": "An action, often a good or brave one.", "translation": ""}], "possibleAnswers": ["A classmate shared her umbrella with me in the rain. It was small, but I felt looked after.", "Someone picked up my books when I dropped them. It only took a second, but I remembered it.", "A teacher said something encouraging when I was struggling. That sentence helped for weeks."]}, {"original": "Would you rather be known as the kindest person in school or the funniest?", "paraphrased": "Which reputation matters more to you: warm and caring, or clever and funny?", "vocab": [{"word": "rather", "definition": "Used to say which of two options you would choose.", "translation": ""}, {"word": "reputation", "definition": "The opinion that other people have about you.", "translation": ""}], "possibleAnswers": ["Kindest, because people remember how you made them feel.", "Funniest, because laughter brings people together and makes hard days lighter.", "Kindest, but I would try to be a little funny too."]}, {"original": "If you saw someone being left out on purpose, what would you do?", "paraphrased": "How would you help a classmate who is being ignored by the group?", "vocab": [{"word": "left out", "definition": "Not included in a group, in a way that feels deliberate.", "translation": ""}, {"word": "ignored", "definition": "When people pretend you are not there or do not answer you.", "translation": ""}], "possibleAnswers": ["I would go and sit with them first, and then invite them to join my group.", "I would tell a teacher quietly, so an adult could help without making it obvious.", "I would message them later and say I noticed. Sometimes that is enough."]}, {"original": "Agree or disagree: it is always better to tell a teacher when you see bullying.", "paraphrased": "Should you report every unkind act, or are there times to handle it yourself?", "vocab": [{"word": "agree", "definition": "To think an idea is right and say yes to it.", "translation": ""}, {"word": "report", "definition": "To tell an adult or person in authority about something that happened.", "translation": ""}], "possibleAnswers": ["I agree, because adults can stop it safely, and staying silent can make it worse.", "I disagree, because sometimes a quiet word with the person works better than telling.", "It depends. Small unkindness can be handled directly, but serious bullying needs an adult."]}, {"original": "What advice would you give to someone who is being bullied online?", "paraphrased": "How would you support a friend receiving cruel messages or comments?", "vocab": [{"word": "advice", "definition": "Helpful suggestions about what someone should do.", "translation": ""}, {"word": "cruel", "definition": "Very unkind, in a way that deliberately hurts someone's feelings.", "translation": ""}], "possibleAnswers": ["I would tell them to save the messages as evidence and block the person, then tell a trusted adult.", "I would say: do not reply, because replies often make it worse. And please talk to someone.", "I would sit with them and help them report it, and remind them it is not their fault."]}, {"original": "Describe a time you stood up for someone. What happened?", "paraphrased": "When did you defend another person, and how did it feel afterwards?", "vocab": [{"word": "stood up", "definition": "Spoke or acted in support of someone who was being treated badly.", "translation": ""}, {"word": "defend", "definition": "To protect someone or say good things about them when they are attacked.", "translation": ""}], "possibleAnswers": ["I told a group to stop laughing at a new student. It felt scary, but also right.", "I defended my friend when someone said she was not good at sport. She thanked me later.", "I did not stand up at the time, and I still regret it. I would do it differently now."]}, {"original": "What is the difference between a joke and a hurtful comment?", "paraphrased": "How do you know when teasing has gone too far?", "vocab": [{"word": "difference", "definition": "The way in which two things are not the same.", "translation": ""}, {"word": "hurtful", "definition": "Making someone feel sad, embarrassed or upset.", "translation": ""}], "possibleAnswers": ["A joke makes everyone laugh, including the person it is about. A hurtful comment targets one person.", "If the other person goes quiet or walks away, it has gone too far.", "A joke is about an idea, and a hurtful comment is about who someone is."]}, {"original": "If you could teach your school one lesson about kindness, what would it be?", "paraphrased": "What single idea about treating people well should every class learn?", "vocab": [{"word": "teach", "definition": "To help people learn a skill or understand an idea.", "translation": ""}, {"word": "kindness", "definition": "Being friendly, generous and considerate towards others.", "translation": ""}], "possibleAnswers": ["I would teach that small kindness is powerful. A five-second good deed can change a whole day.", "I would teach that silence is a choice. Walking past someone who is hurt still sends a message.", "I would teach that everyone is fighting something you cannot see, so be gentle."]}, {"original": "Who is the kindest person you know, and what do they do that shows it?", "paraphrased": "Which person in your life quietly helps others, and how?", "vocab": [{"word": "kindest", "definition": "The most caring and gentle person.", "translation": ""}, {"word": "quietly", "definition": "Without drawing attention to yourself or boasting.", "translation": ""}], "possibleAnswers": ["My neighbour checks on my gran every morning. She never mentions it to anyone.", "My football coach notices when someone is tired and gives them a rest without shaming them.", "My mum listens to everyone, even when she is busy. That is her kindness."]}, {"original": "What is worse: being teased about your appearance or being ignored completely?", "paraphrased": "Which hurts more — unkind words, or silence from people you like?", "vocab": [{"word": "worse", "definition": "More painful or unpleasant than the other choice.", "translation": ""}, {"word": "teased", "definition": "Laughed at or made fun of in an unkind way.", "translation": ""}], "possibleAnswers": ["Being teased is worse, because the words stay in your head.", "Being ignored hurts more, because it feels like you do not exist.", "Both are painful, but silence can be harder to understand."]}, {"original": "Imagine you could invent a 'kindness club' at school. What would members do each week?", "paraphrased": "What weekly activity would make your school a friendlier place?", "vocab": [{"word": "invent", "definition": "To create something new that did not exist before.", "translation": ""}, {"word": "members", "definition": "People who belong to a club or group.", "translation": ""}], "possibleAnswers": ["Each week we would write one honest thank-you note to a different person in school.", "We would run a 'sit with us' table at lunch, so nobody has to eat alone.", "We would choose one small challenge, like giving three genuine compliments a day."]}, {"original": "If someone apologised to you after being unkind, would you forgive them? Why or why not?", "paraphrased": "How easy is it for you to accept an apology, and what makes it feel real?", "vocab": [{"word": "apologised", "definition": "Said sorry for something hurtful you did.", "translation": ""}, {"word": "forgive", "definition": "To stop feeling angry with someone who hurt you.", "translation": ""}], "possibleAnswers": ["I would forgive them if the apology felt honest and they changed their behaviour.", "I find it hard to forgive quickly, but I can usually get there with time.", "I would forgive them, because holding anger hurts me more than it hurts them."]}]}]}, {"category": "The World and the Future", "topics": [{"title": "Hobbies and Free Time (12 questions)", "slug": "hobbiesfreetime", "level": "A2-B1", "questions": [{"original": "What is your favourite way to spend a lazy afternoon, and what makes it feel so good?", "paraphrased": "Which slow, easy activity makes your free time feel perfect?", "vocab": [{"word": "lazy", "definition": "not wanting to work or move; relaxed", "translation": ""}, {"word": "afternoon", "definition": "the time between lunch and evening", "translation": ""}], "possibleAnswers": ["I love reading comics in my room with music on. It feels good because nobody can interrupt me.", "I usually play video games with my best friend online. It helps me forget about school for a while.", "Honestly, I just lie on the sofa and do nothing. After a busy week, doing nothing is the best feeling."]}, {"original": "If you could become brilliant at any hobby overnight, which one would you pick?", "paraphrased": "Which hobby would you love to be instantly good at, and why that one?", "vocab": [{"word": "brilliant", "definition": "extremely good at something", "translation": ""}, {"word": "overnight", "definition": "very quickly; by the next morning", "translation": ""}], "possibleAnswers": ["I would pick playing the guitar, because I love music and I could play all my favourite songs.", "Probably skating. It looks so cool, and I always fall over when I try.", "I would choose drawing. I want to make pictures that look real."]}, {"original": "Would you rather spend your free time making something with your hands or watching something on a screen?", "paraphrased": "Do you prefer creating things yourself or enjoying what other people have made?", "vocab": [{"word": "making", "definition": "creating or building something", "translation": ""}, {"word": "screen", "definition": "the flat surface of a phone, computer or TV", "translation": ""}], "possibleAnswers": ["I like making things, like models or bracelets. It feels great when I finish them.", "I prefer watching, especially films and football. I am tired after school, so I want to relax.", "Both, really. I paint at the weekend and watch series in the evening."]}, {"original": "Which hobby sounds the most boring, and how would you make it fun?", "paraphrased": "What activity seems dullest to you, and what would you change about it?", "vocab": [{"word": "boring", "definition": "not interesting; makes you feel tired", "translation": ""}, {"word": "dullest", "definition": "the most boring", "translation": ""}], "possibleAnswers": ["Running on its own sounds boring. I would listen to music and run with friends.", "I think chess is dull, but it might be fun with a timer and a funny prize.", "Collecting stamps sounds slow. I would make it into a game with points."]}, {"original": "What advice would you give a shy friend who wants to start a new hobby but feels nervous?", "paraphrased": "What would you tell a nervous friend who wants to try something new?", "vocab": [{"word": "shy", "definition": "quiet and not confident around other people", "translation": ""}, {"word": "nervous", "definition": "worried or scared about something", "translation": ""}], "possibleAnswers": ["I would say: start small and do it with a friend. Nobody is watching you as much as you think.", "Try a class for beginners, where everyone is new. It is okay to make mistakes.", "I would tell them to watch a video first at home, so they feel ready."]}, {"original": "Tell me about your ideal weekend if money and school were no problem.", "paraphrased": "Describe your perfect weekend with no limits at all.", "vocab": [{"word": "ideal", "definition": "perfect; exactly what you want", "translation": ""}, {"word": "limit", "definition": "a rule or fact that stops you doing something", "translation": ""}], "possibleAnswers": ["I would go to the beach with my friends, play football, and eat ice cream until late.", "I would sleep until eleven, play video games all afternoon, and watch a film at night.", "I would visit a big city, see a concert, and stay in a hotel with a pool."]}, {"original": "Who in your life has a hobby you secretly wish you had, and what do they do?", "paraphrased": "Which person's hobby makes you a little jealous, and why?", "vocab": [{"word": "secretly", "definition": "without telling other people", "translation": ""}, {"word": "jealous", "definition": "wanting something that someone else has", "translation": ""}], "possibleAnswers": ["My brother plays the drums. He is in a band, and I wish I could do that.", "My cousin paints amazing pictures. Sometimes I wish I had her talent.", "My grandma bakes the best cakes. I wish I had the time to learn like her."]}, {"original": "Do you agree that free time is the most important part of the day?", "paraphrased": "Do you think how you spend your free time matters more than school or work?", "vocab": [{"word": "important", "definition": "having a big effect; worth caring about", "translation": ""}, {"word": "matter", "definition": "to be important", "translation": ""}], "possibleAnswers": ["Yes, because it is the only time you can choose what to do. School is not a choice.", "No, school matters more for my future. Free time is just for relaxing.", "I think they are both important. Free time keeps me happy, and school keeps me going."]}, {"original": "Describe a hobby you used to love but do not do any more.", "paraphrased": "What hobby did you leave behind, and what made you stop?", "vocab": [{"word": "used to", "definition": "something you did in the past but do not do now", "translation": ""}, {"word": "left behind", "definition": "stopped doing or forgot", "translation": ""}], "possibleAnswers": ["I used to collect football cards. I stopped when I got interested in music.", "I loved drawing, but school got busy and I never picked up a pen again.", "I did gymnastics when I was little. I stopped because the training was too hard."]}, {"original": "When was the last time a hobby made you lose track of time completely?", "paraphrased": "Tell me about a moment when you were so focused on a hobby that hours flew by.", "vocab": [{"word": "lose track", "definition": "forget how much time has passed", "translation": ""}, {"word": "focused", "definition": "giving all your attention to one thing", "translation": ""}], "possibleAnswers": ["Last Saturday I was building a model, and suddenly it was midnight. I could not believe it.", "When I play the piano, I forget everything. My mum has to call me twice for dinner.", "I was drawing a poster for school and looked up, and two hours had passed."]}, {"original": "Do you prefer a hobby you do alone or one you do with friends?", "paraphrased": "Would you rather enjoy your free time by yourself or together with other people?", "vocab": [{"word": "prefer", "definition": "like one thing more than another", "translation": ""}, {"word": "alone", "definition": "with no other people", "translation": ""}], "possibleAnswers": ["I prefer being alone, because I can do exactly what I want.", "With friends, definitely. Everything is funnier when you share it.", "It depends on my mood. Sometimes I want quiet, sometimes I want company."]}, {"original": "Imagine you could design a clubhouse for your favourite hobby. What would be inside it?", "paraphrased": "If you had a special room just for the thing you love most, what would it have?", "vocab": [{"word": "design", "definition": "to plan how something will look or work", "translation": ""}, {"word": "inside", "definition": "in the room or building", "translation": ""}], "possibleAnswers": ["For gaming, I would put in big screens, comfy chairs, and a fridge full of snacks.", "I would have art on every wall, lots of paper, and a table for my friends to draw at.", "A music room with guitars, drums, and soft lights so it feels like a real stage."]}]}, {"title": "Sport and a Healthy Life (12 questions)", "slug": "sporthealthylife", "level": "A2-B1", "questions": [{"original": "Which sport do you enjoy most, and what do you love about it?", "paraphrased": "What is your favourite sport to play or watch, and why?", "vocab": [{"word": "enjoy", "definition": "to like doing something", "translation": ""}, {"word": "love", "definition": "to like something very much", "translation": ""}], "possibleAnswers": ["I love football because it is fast and I play with my friends every weekend.", "Swimming is my favourite. It is quiet, and I feel free in the water.", "I enjoy basketball. I like the feeling when a shot goes in."]}, {"original": "Do you prefer training for a marathon or learning a dance routine for a school show?", "paraphrased": "Would you rather work on your fitness alone or perform in front of people?", "vocab": [{"word": "training", "definition": "practising to get better at something", "translation": ""}, {"word": "routine", "definition": "a set of moves you learn and repeat", "translation": ""}], "possibleAnswers": ["A marathon, because I like running and I would love to finish one.", "A dance routine, because I am shy but I would like to try performing.", "Neither, honestly. I would rather swim or play football."]}, {"original": "Some people say winning is the only thing that matters in sport. Do you agree?", "paraphrased": "Is it more important to win, or to enjoy playing?", "vocab": [{"word": "winning", "definition": "being the best in a game or race", "translation": ""}, {"word": "matters", "definition": "is important", "translation": ""}], "possibleAnswers": ["I agree. If you play to win, you push yourself harder.", "No. Playing with friends and having fun is enough for me.", "Winning is nice, but I think trying your best matters more."]}, {"original": "What is the most frustrating rule in any sport, and how would you change it?", "paraphrased": "Which rule in sport annoys you the most, and what would you do differently?", "vocab": [{"word": "frustrating", "definition": "making you feel annoyed or upset", "translation": ""}, {"word": "annoy", "definition": "to make someone feel slightly angry", "translation": ""}], "possibleAnswers": ["In football, the offside rule confuses me. I would make it simpler.", "I hate timeouts in basketball. They stop the game when it is exciting.", "In swimming, false starts are so strict. I would give one warning first."]}, {"original": "If you could add one new sport to your school year, what would it be?", "paraphrased": "Which sport would you love to see on the school timetable?", "vocab": [{"word": "add", "definition": "to put something extra in", "translation": ""}, {"word": "timetable", "definition": "a plan that shows when lessons or activities happen", "translation": ""}], "possibleAnswers": ["Rock climbing. It is a great workout and it looks exciting.", "I would add yoga, because we all need to relax more.", "Table tennis. It is cheap, fun, and anyone can play."]}, {"original": "How would you help someone who wants to get fit but hates exercise?", "paraphrased": "What advice would you give a friend who finds sport boring but wants to be healthier?", "vocab": [{"word": "fit", "definition": "strong and healthy", "translation": ""}, {"word": "hate", "definition": "to dislike something very much", "translation": ""}], "possibleAnswers": ["Start with something fun, like dancing or walking with music. Do not think of it as exercise.", "Find a friend to do it with. It is easier when you are not alone.", "Do ten minutes a day. Small habits are better than big plans you cannot keep."]}, {"original": "What would happen if schools had no competitive sport at all?", "paraphrased": "How would school change if there were no matches, races, or winners?", "vocab": [{"word": "competitive", "definition": "wanting to win; treating something as a contest", "translation": ""}, {"word": "match", "definition": "a game between two teams or players", "translation": ""}], "possibleAnswers": ["More students would join in, because nobody would feel scared of losing.", "School would be calmer, but we might miss the excitement of match day.", "Some kids would stop being active, and that would be bad."]}, {"original": "Tell me about a sport you have never tried but would love to try.", "paraphrased": "Which sport is on your list to try one day, and what attracts you?", "vocab": [{"word": "tried", "definition": "done or tested something", "translation": ""}, {"word": "attracts", "definition": "makes you interested or excited", "translation": ""}], "possibleAnswers": ["Ice hockey. It looks fast and a bit dangerous, which makes it exciting.", "I would love to try surfing. Standing on a board in the sea sounds amazing.", "Archery. It needs focus, and I would like to see if I can hit the target."]}, {"original": "When do you feel healthiest and strongest during the week?", "paraphrased": "At what moment in the week do you feel best in your body?", "vocab": [{"word": "healthiest", "definition": "feeling most well and strong", "translation": ""}, {"word": "strongest", "definition": "having the most power", "translation": ""}], "possibleAnswers": ["After football training on Wednesday. I am tired, but I feel strong.", "On weekends, because I sleep more and eat better food.", "In the morning after a good breakfast. I have energy for the whole day."]}, {"original": "Who is your sporting hero, and what impresses you most about them?", "paraphrased": "Which athlete do you admire, and what do they do that you find amazing?", "vocab": [{"word": "hero", "definition": "a person you admire", "translation": ""}, {"word": "impresses", "definition": "makes you feel respect or admiration", "translation": ""}], "possibleAnswers": ["My hero is Lionel Messi. He makes difficult things look easy.", "I admire Simone Biles. She is brave and she never gives up.", "My older sister, because she trains every day even when she is tired."]}, {"original": "Do you enjoy team sports more than sports you do on your own?", "paraphrased": "Do you like playing with others, or do you prefer to exercise by yourself?", "vocab": [{"word": "team", "definition": "a group of people who play together", "translation": ""}, {"word": "exercise", "definition": "physical activity that keeps you healthy", "translation": ""}], "possibleAnswers": ["Team sports, because the energy of the group makes me play better.", "On my own. I can go at my own speed and think about nothing.", "Both. Teams are fun, but running alone helps me clear my head."]}, {"original": "Invent a brand-new Olympic sport. What would the rules be?", "paraphrased": "If you could create a sport for the whole world to watch, what would players do?", "vocab": [{"word": "invent", "definition": "to think of and make something new", "translation": ""}, {"word": "rules", "definition": "the instructions that tell you how to play", "translation": ""}], "possibleAnswers": ["A mix of football and trampolines. You score by jumping high and kicking the ball in.", "Underwater hockey with glow sticks. It would look amazing on TV.", "A race where teams solve puzzles and run. The fastest brain and legs win."]}]}, {"title": "Food and Favourites (12 questions)", "slug": "foodfavourites", "level": "A2-B1", "questions": [{"original": "Tell me about the best meal you have ever eaten.", "paraphrased": "What dish made you think 'this is amazing', and where were you?", "vocab": [{"word": "meal", "definition": "the food you eat at one time, like lunch or dinner", "translation": ""}, {"word": "dish", "definition": "a particular kind of food that is cooked", "translation": ""}], "possibleAnswers": ["My mum's chicken soup when I was ill. It tasted like love.", "A pizza in Italy on holiday. The cheese was so fresh.", "My birthday cake last year. It was chocolate and it had my name on it."]}, {"original": "Which would you choose: the same meal every day, or a new dish every week?", "paraphrased": "Do you prefer familiar food, or do you like exploring new flavours?", "vocab": [{"word": "familiar", "definition": "something you know well", "translation": ""}, {"word": "flavours", "definition": "the different tastes of food, like sweet or salty", "translation": ""}], "possibleAnswers": ["The same meal every day. I know what I like, and I do not like surprises.", "A new dish every week. Food is an adventure, and I want to taste everything.", "A mix. I have favourites, but I like trying one new thing each week."]}, {"original": "What is the strangest food you have ever tried, and would you eat it again?", "paraphrased": "Which unusual food surprised you most, and did you like it?", "vocab": [{"word": "strangest", "definition": "most unusual", "translation": ""}, {"word": "unusual", "definition": "not common; different from what you expect", "translation": ""}], "possibleAnswers": ["Fried insects at a market. They were crunchy, but I would not eat them again.", "Durian fruit. It smells terrible, but the taste is not so bad.", "Cheese with worms inside. I was brave, but no, never again."]}, {"original": "If you could eat food from only one country for a whole year, which country would you choose?", "paraphrased": "Which country's cooking would you happily live on for twelve months?", "vocab": [{"word": "country", "definition": "a nation with its own land and people", "translation": ""}, {"word": "cooking", "definition": "the activity of preparing food", "translation": ""}], "possibleAnswers": ["Italy. Pasta, pizza, ice cream — I would never get bored.", "Japan. I love sushi and the food always looks beautiful.", "Mexico. Tacos and spicy food are my favourite."]}, {"original": "Breakfast is the most important meal of the day. Do you agree?", "paraphrased": "Is breakfast really the meal that matters most, or is that just a saying?", "vocab": [{"word": "breakfast", "definition": "the first meal of the day, in the morning", "translation": ""}, {"word": "saying", "definition": "a common phrase people repeat", "translation": ""}], "possibleAnswers": ["I agree. Without breakfast I am tired and grumpy in class.", "Not really. I skip it, and I feel fine.", "It is important, but I think dinner matters more because we eat together."]}, {"original": "What would you tell a friend who wants to learn to cook but is scared of making mistakes?", "paraphrased": "How would you help a nervous friend feel brave enough to cook?", "vocab": [{"word": "learn", "definition": "to get a new skill by practising", "translation": ""}, {"word": "scared", "definition": "frightened or worried", "translation": ""}], "possibleAnswers": ["Start with something easy, like eggs or pasta. Mistakes still taste good.", "Cook with me the first time. We can laugh at the disasters together.", "Watch a video, then copy it. You will improve fast."]}, {"original": "Describe your perfect birthday dinner, course by course.", "paraphrased": "What would you eat first, next, and last at your dream birthday meal?", "vocab": [{"word": "course", "definition": "one part of a meal, like a starter or dessert", "translation": ""}, {"word": "perfect", "definition": "the best possible; with no problems", "translation": ""}], "possibleAnswers": ["Starter: soup. Main: roast chicken and chips. Dessert: chocolate cake with ice cream.", "I would have pizza first, then pasta, then a huge ice-cream sundae.", "My perfect dinner is simple: my mum's curry, rice, and a mango dessert."]}, {"original": "Imagine everyone in the world could only eat one type of food. What would happen?", "paraphrased": "If all people had to share the same diet, how would life change?", "vocab": [{"word": "imagine", "definition": "to picture something in your mind", "translation": ""}, {"word": "diet", "definition": "the kinds of food a person usually eats", "translation": ""}], "possibleAnswers": ["People would fight over the best version of that food. It would be chaos.", "We would all be healthier, maybe, if the food was good for us.", "Food would lose its fun. I would miss birthdays and festivals."]}, {"original": "When do you feel like cooking for yourself, and what do you make?", "paraphrased": "At what moments do you enjoy preparing your own food?", "vocab": [{"word": "feel like", "definition": "to want to do something", "translation": ""}, {"word": "preparing", "definition": "making food ready to eat", "translation": ""}], "possibleAnswers": ["On Sunday evenings. I make pasta with cheese and it is simple.", "When I am stressed. Cooking slowly helps me calm down.", "I never cook, honestly. My parents do it, and I am happy with that."]}, {"original": "Who cooks the best food in your family, and what is their special dish?", "paraphrased": "Which person in your family is the best cook, and what do they make?", "vocab": [{"word": "cooks", "definition": "prepares food by heating it", "translation": ""}, {"word": "special", "definition": "different and better than usual", "translation": ""}], "possibleAnswers": ["My dad makes the best pancakes. He flips them high and never breaks them.", "My grandma. Her soup is famous in our family.", "My mum. Her curry is spicy and warm, and everyone asks for more."]}, {"original": "Which snack do you reach for when you need energy?", "paraphrased": "What food do you grab when you are hungry between meals?", "vocab": [{"word": "snack", "definition": "a small amount of food eaten between meals", "translation": ""}, {"word": "energy", "definition": "the strength to do things", "translation": ""}], "possibleAnswers": ["A banana. It is quick and it gives me power for football.", "Crisps, but then I feel hungry again after ten minutes.", "Nuts and an apple. My mum packs them for me."]}, {"original": "Picture your own little café. What would you serve, and what would it look like?", "paraphrased": "If you opened a small place for food and friends, what would be on the menu?", "vocab": [{"word": "café", "definition": "a small, friendly restaurant", "translation": ""}, {"word": "serve", "definition": "to give food to customers", "translation": ""}], "possibleAnswers": ["I would serve milkshakes and waffles, with bright colours and soft music.", "A book café: coffee, cake, and quiet corners to read.", "I would make it look like a garden, with plants and tables outside."]}]}, {"title": "Travel and Places (12 questions)", "slug": "travelplaces", "level": "A2-B1", "questions": [{"original": "Describe your favourite place in the world and what makes it special.", "paraphrased": "Which place do you love most, and what feelings does it give you?", "vocab": [{"word": "favourite", "definition": "the one you like best", "translation": ""}, {"word": "special", "definition": "different and important to you", "translation": ""}], "possibleAnswers": ["The beach near my grandparents' house. It is quiet, and the water is warm.", "My school library. It smells like books and it is my calm place.", "A mountain village we visited. The air was clean and the views were amazing."]}, {"original": "Which sounds better to you: a hot beach holiday or a cold mountain village?", "paraphrased": "Do you prefer relaxing in the sun or exploring somewhere fresh and cool?", "vocab": [{"word": "holiday", "definition": "a time when you do not work or go to school; a trip", "translation": ""}, {"word": "rather", "definition": "would prefer", "translation": ""}], "possibleAnswers": ["A hot beach. I love swimming and sleeping in the sun.", "A cold mountain village. I like walking and the air is fresh.", "The beach, but only if my friends come too."]}, {"original": "If you could visit any country tomorrow, where would you go and why?", "paraphrased": "Which country is at the top of your travel list right now?", "vocab": [{"word": "visit", "definition": "to go and see a place or person", "translation": ""}, {"word": "country", "definition": "a nation with its own land and people", "translation": ""}], "possibleAnswers": ["Japan. I want to see Tokyo and eat real ramen.", "Brazil. The music, the football, and the beaches all sound amazing.", "I would stay in my own country and explore the places I have never seen."]}, {"original": "What is the worst journey you have ever had, and what went wrong?", "paraphrased": "Tell me about a trip that went badly, from start to finish.", "vocab": [{"word": "journey", "definition": "a trip from one place to another", "translation": ""}, {"word": "badly", "definition": "in a poor or unpleasant way", "translation": ""}], "possibleAnswers": ["We missed our train and waited five hours in the rain.", "A flight was delayed all night, and I slept on the airport floor.", "The car broke down in the middle of nowhere. It was scary but funny later."]}, {"original": "It is better to travel slowly and see fewer places. Do you agree?", "paraphrased": "Would you rather stay longer in one place or rush to see everything?", "vocab": [{"word": "slowly", "definition": "at a low speed; without hurry", "translation": ""}, {"word": "rush", "definition": "to move or do something too fast", "translation": ""}], "possibleAnswers": ["I agree. When you stay longer, you really learn a place.", "No. I want to see as much as possible, even if it is tiring.", "It depends. Slowly for holidays, quickly for a short weekend trip."]}, {"original": "Where would you take a friend who is visiting your town for the first time?", "paraphrased": "What advice would you give someone seeing your town for the first time?", "vocab": [{"word": "advice", "definition": "a suggestion about what to do", "translation": ""}, {"word": "visiting", "definition": "going to see a place or person", "translation": ""}], "possibleAnswers": ["Go to the market in the morning. The food is fresh and cheap.", "Walk by the river at sunset. It is the most beautiful view.", "Avoid the main street and find the small park with the old tree."]}, {"original": "Imagine your dream holiday. Where would you go, and who would you take?", "paraphrased": "Describe the trip you would choose if you could have anything you wanted.", "vocab": [{"word": "dream", "definition": "the thing you hope for most", "translation": ""}, {"word": "trip", "definition": "a journey or visit", "translation": ""}], "possibleAnswers": ["I would go to Iceland with my best friend to see the northern lights.", "A road trip along the coast with my family and lots of music.", "I would take my grandma to the seaside, because she loves the sea."]}, {"original": "What would the world be like if everyone could travel anywhere for free?", "paraphrased": "How would life change if planes, trains, and buses cost nothing?", "vocab": [{"word": "free", "definition": "costing no money", "translation": ""}, {"word": "change", "definition": "to become different", "translation": ""}], "possibleAnswers": ["The world would feel smaller. You could make friends everywhere.", "Airports would be chaotic, and popular places would be too crowded.", "More people would understand other cultures, and that would be good."]}, {"original": "When was the last time you went somewhere new, and what did you notice first?", "paraphrased": "Think of a recent place you saw for the first time. What surprised you?", "vocab": [{"word": "recent", "definition": "happening not long ago", "translation": ""}, {"word": "noticed", "definition": "saw or realised something", "translation": ""}], "possibleAnswers": ["Last month we went to a new city. The noise hit me first.", "A friend's village. It was so quiet that I could hear birds.", "I visited a museum I had never seen. The building itself was beautiful."]}, {"original": "Who would you love to travel with, and where would you go together?", "paraphrased": "Which person would make the best travel companion for you?", "vocab": [{"word": "travel", "definition": "to go on a journey", "translation": ""}, {"word": "companion", "definition": "a person you spend time with", "translation": ""}], "possibleAnswers": ["My best friend. We laugh a lot, and we both love food.", "My older brother. He speaks languages and he knows how to plan.", "My whole family. It is chaotic, but we make great memories."]}, {"original": "Which place makes you feel calm as soon as you arrive?", "paraphrased": "Where do you go when you need to relax and breathe?", "vocab": [{"word": "calm", "definition": "peaceful and quiet", "translation": ""}, {"word": "arrive", "definition": "to reach a place", "translation": ""}], "possibleAnswers": ["The library. As soon as I walk in, everything gets quiet.", "My grandma's garden. The smell of flowers calms me.", "The swimming pool. Water makes me feel light."]}, {"original": "Picture a treehouse or a hut anywhere in the world. Where would you build it?", "paraphrased": "If you had a small hidden home in nature, what would its view be?", "vocab": [{"word": "treehouse", "definition": "a small room or platform built in a tree", "translation": ""}, {"word": "view", "definition": "what you can see from a place", "translation": ""}], "possibleAnswers": ["In the forest, with a window facing the mountains.", "On a beach, so I could hear the waves every night.", "In my own garden. It would be my secret place."]}]}, {"title": "Future Dreams and Jobs (12 questions)", "slug": "futuredreamsjobs", "level": "A2-B1", "questions": [{"original": "What is your dream job, and what would a normal day look like?", "paraphrased": "Which job do you hope to have one day, and what would you do every day?", "vocab": [{"word": "dream", "definition": "the thing you hope for most", "translation": ""}, {"word": "normal", "definition": "usual; like most days", "translation": ""}], "possibleAnswers": ["I want to be a game designer. I would make levels and test them with friends.", "A vet. I would help sick animals and their owners every day.", "A teacher, like my English teacher. I would help kids who find school hard."]}, {"original": "Do you see yourself working outdoors or in an office?", "paraphrased": "Would you rather have a job in the fresh air or a job at a desk?", "vocab": [{"word": "outdoors", "definition": "outside, not in a building", "translation": ""}, {"word": "office", "definition": "a room where people work at desks", "translation": ""}], "possibleAnswers": ["Outdoors. I cannot sit still for eight hours.", "An office, because I like computers and it is warm in winter.", "A mix. Maybe work outside in summer and inside in winter."]}, {"original": "If you could invent something that makes life easier, what would it be?", "paraphrased": "What machine or app would you create to solve a daily problem?", "vocab": [{"word": "invent", "definition": "to think of and make something new", "translation": ""}, {"word": "easier", "definition": "less difficult", "translation": ""}], "possibleAnswers": ["A robot that packs my school bag and finishes my homework.", "A translator earring so I could talk to anyone in the world.", "A machine that makes healthy food taste like chocolate."]}, {"original": "It is more important to love your job than to earn a lot of money. Do you agree?", "paraphrased": "Is a job you enjoy better than a job that pays well?", "vocab": [{"word": "earn", "definition": "to get money for your work", "translation": ""}, {"word": "pays", "definition": "gives you money for working", "translation": ""}], "possibleAnswers": ["I agree. You spend too many hours at work to be unhappy.", "No. Money lets you help your family and live comfortably.", "Both matter. I would like a job I like that also pays enough."]}, {"original": "Which job would you hate the most, and why?", "paraphrased": "What kind of work would you never want to do?", "vocab": [{"word": "hate", "definition": "to dislike something very much", "translation": ""}, {"word": "work", "definition": "a job or activity that needs effort", "translation": ""}], "possibleAnswers": ["A job in a call centre. Talking on the phone all day sounds exhausting.", "Working night shifts in a hospital. I would be too tired.", "Sitting at a desk doing the same thing for years. I need variety."]}, {"original": "What would you tell your future self about choosing a job?", "paraphrased": "What advice would you give yourself before you decide on a career?", "vocab": [{"word": "advice", "definition": "a suggestion about what to do", "translation": ""}, {"word": "career", "definition": "the job or series of jobs you do in life", "translation": ""}], "possibleAnswers": ["Try different things before you decide. You do not have to choose at sixteen.", "Choose something that helps people. It will feel more meaningful.", "Do not worry about money at first. Learn skills, and the rest will follow."]}, {"original": "Describe your life ten years from now, from your job to where you live.", "paraphrased": "What does an ordinary day look like for you as a young adult?", "vocab": [{"word": "adult", "definition": "a grown-up person", "translation": ""}, {"word": "ordinary", "definition": "normal; not special", "translation": ""}], "possibleAnswers": ["I live in a small flat near the sea, and I work as a designer.", "I am at university, studying to be a doctor, and I share a house with friends.", "I travel for work and come home at weekends. It sounds busy but fun."]}, {"original": "Imagine the world fifty years from now. Describe one big change.", "paraphrased": "What will be very different about life in the future?", "vocab": [{"word": "imagine", "definition": "to picture something in your mind", "translation": ""}, {"word": "change", "definition": "something becoming different", "translation": ""}], "possibleAnswers": ["Cars will drive themselves, and people will work from anywhere.", "Cities will have more green space, and the air will be cleaner.", "School will be different. We might learn with virtual reality."]}, {"original": "When you think about the future, what makes you feel excited?", "paraphrased": "Which part of growing up are you looking forward to most?", "vocab": [{"word": "excited", "definition": "happy and enthusiastic about something", "translation": ""}, {"word": "growing up", "definition": "becoming older and more adult", "translation": ""}], "possibleAnswers": ["Having my own place and making my own rules.", "Choosing what to study and who to spend my time with.", "Travelling on my own. I want to see the world without my parents."]}, {"original": "Who is your role model for the kind of life you would like to have?", "paraphrased": "Which person's life do you admire, and what do they do?", "vocab": [{"word": "role model", "definition": "a person you try to be like", "translation": ""}, {"word": "admire", "definition": "to respect and like someone", "translation": ""}], "possibleAnswers": ["My aunt. She has a job she loves and still finds time for family.", "A YouTuber who travels and works with animals. That life looks free.", "My dad. He works hard and stays kind."]}, {"original": "Do you think being famous would be fun, or is a quiet life better?", "paraphrased": "Would you like to be well known, or do you prefer privacy?", "vocab": [{"word": "famous", "definition": "known by many people", "translation": ""}, {"word": "privacy", "definition": "time when you are alone and not watched", "translation": ""}], "possibleAnswers": ["A quiet life. I would hate cameras and people following me.", "Famous would be fun for a while, but I think it gets lonely.", "I would like to be famous for my work, not for my private life."]}, {"original": "Invent a job that does not exist yet but the future will need. What is it?", "paraphrased": "What new kind of work will appear as the world changes?", "vocab": [{"word": "invent", "definition": "to think of and make something new", "translation": ""}, {"word": "need", "definition": "to require something", "translation": ""}], "possibleAnswers": ["A robot teacher who helps children learn at their own speed.", "Someone who designs homes for people living on other planets.", "A climate fixer who helps cities become greener."]}]}]}];
